window.NursingLearningData = {"version":1,"chapters":[{"id":"ch01","number":1,"title":"绪论","page":"ch01-introduction.html","lab":"ch01-learning-lab.html","core":[{"id":"ch01-core-1","title":"课程定位","answer":"基础护理把基本理论、知识和技能用于患者的基本需要与安全。","reason":"具体考法：常把课程任务放进新护士的工作情境中判断。","source":"教材第1—2页"},{"id":"ch01-core-2","title":"学习对象","answer":"学习不能只记操作步骤，还要理解对象、条件、风险和评价标准。","reason":"具体考法：题干改变患者条件时，要同步改变护理选择。","source":"教材第2—3页"},{"id":"ch01-core-3","title":"护理程序","answer":"评估贯穿全过程，随后识别问题、计划、实施并评价。","reason":"具体考法：方案题先问资料是否充分，再排优先级。","source":"教材第3—4页"},{"id":"ch01-core-4","title":"整体护理","answer":"同一技术要同时照顾生理安全、心理感受、文化与家庭支持。","reason":"具体考法：病例常用隐私、焦虑和参与决策检验整体观。","source":"教材第3—4页"},{"id":"ch01-core-5","title":"专业素质","answer":"慎独、沟通、协作、观察与规范操作共同保证护理质量。","reason":"具体考法：无人监督仍按制度执行是慎独的典型线索。","source":"教材第4—5页"}],"numbers":[{"id":"ch01-number-1","title":"护理程序步骤","answer":"评估—诊断/问题—计划—实施—评价","condition":"按完整顺序识别，评估贯穿始终","source":"教材第3—4页"}],"compare":[{"title":"熟练操作/优质护理","items":["A：动作完成","B：还包含风险判断、沟通与评价","决定性区别：能做不等于能解释和复评"]},{"title":"共同原则/个体化","items":["A：遵守同一安全底线","B：依据患者差异调整方法","决定性区别：同病种不等于同一计划"]},{"title":"独立判断/单独行动","items":["A：在职责内作专业判断","B：需要时及时协作和报告","决定性区别：独立不等于拒绝团队"]}],"questions":[{"id":"ch01-exam-1","title":"女性患者，35岁，因近1个月怕热、多汗、情绪激动，且经常腹泻、心悸而门诊检查。体检:甲状腺肿大,两手微抖,眼球稍突。实验室检查：T36．2nmol／L，T4254nmol／L。以甲状腺功能亢进收入院。你认为下列哪项不属于护理诊断","topic":"课程定位","options":["A. 焦虑","B. 营养失调","C. 甲状腺肿大","D. 知识缺乏","E. 自我形象紊乱"],"answer":"正确答案：C．甲状腺肿大","correct":["C"],"source":"教材第1—2页","paper":"山西医科大学2016｜单项选择题"},{"id":"ch01-exam-2","title":"患者张某，30岁，因发热、咳嗽而入院，诊断为“肺炎”，体温39.5℃，皮肤发红，接触皮肤有热感，呼吸、心率加快。该病人的护理诊断之一：“体温过高：与病原菌感染有关”，主要诊断依据为（）","topic":"课程定位","options":["A. 体温39.5℃","B. 呼吸加快","C. 皮肤发红","D. 接触皮肤有热感","E. 心率加快"],"answer":"正确答案：A．体温39.5℃","correct":["A"],"source":"教材第1—2页","paper":"暨南大学2021｜单项选择题"},{"id":"ch01-exam-3","title":"尤先生，30岁。因发热、胸痛、咳嗽2日入院。体温40℃，右下肺闻及湿啰音。血白细胞计数120×109/L。入院诊断，发热待查，肺炎？该病人的首优护理诊断是:","topic":"护理程序步骤","options":["A. 气体交换受损","B. 低效性呼吸形态","C. 体温过高","D. 疼痛:胸痛","E. 清理呼吸道无效"],"answer":"正确答案：C．体温过高","correct":["C"],"source":"教材第3—4页","paper":"河南科技大学2019｜单项选择题"},{"id":"ch01-exam-4","title":"某男,21岁,因肺炎入院，护理评估:体温39.4℃，呼吸困难，咳铁锈色痰。下列护理诊断正确的是，：","topic":"护理程序步骤","options":["A. 肺炎球菌肺炎","B. 食欲下降:与高热有关","C. 高热","D. 体温过高:与致病菌引起的肺部感染有关","E. 呼吸异常:与肺炎有关"],"answer":"正确答案：D．体温过高:与致病菌引起的肺部感染有关","correct":["D"],"source":"教材第3—4页","paper":"中南大学2018｜单项选择题"},{"id":"ch01-exam-5","title":"李先生，73岁，“因呕血、黑便3小时”入院，初步诊断为“门静脉高压症、食管胃底曲张静脉破裂出血”，当前护理诊断中属于首优问题的是","topic":"护理程序步骤","options":["A. 知识缺乏","B. 体液不足","C. 营养失调：低于机体需要量","D. 焦虑","E. 有误吸的危险"],"answer":"正确答案：B．体液不足","correct":["B"],"source":"教材第3—4页","paper":"青岛大学2013｜单项选择题"},{"id":"ch01-exam-6","title":"患者，女，24岁。诊断为系统性红斑狼疮，针对“皮肤完整性受损”护理诊断采取的护理措施中不正确的是","topic":"护理程序步骤","options":["A. 忌日光","B. 忌紫外线","C. 忌化妆品","D. 碱性肥皂洗","E. 温水湿敷"],"answer":"正确答案：D．碱性肥皂洗","correct":["D"],"source":"教材第3—4页","paper":"青岛大学2009｜单项选择题"},{"id":"ch01-exam-7","title":"导致护理目标部分实现或完全没有实现的原因可能包括（）","topic":"护理程序步骤","options":["A. 护理诊断错误","B. 护理计划可行性差","C. 护理措施未有效落实","D. 患者出现新的问题"],"answer":"正确答案：A．护理诊断错误；B．护理计划可行性差；C．护理措施未有效落实；D．患者出现新的问题","correct":["A","B","C","D"],"source":"教材第3—4页","paper":"浙江中医药大学2021｜多项选择题"},{"id":"ch01-exam-8","title":"患者男，42岁，被汽车撞击左上腹部后收住院，住院期间下床活动时出现腹痛、面色苍白、出冷汗。体温37.5℃，脉搏120次/分，血压80/60mmHg，腹部压痛、反跳痛、和移动性浊音（+），腹腔穿刺抽出不凝血，此时该病人最重要的护理诊断是","topic":"课程定位","options":["A. 焦虑","B. 疼痛","C. 休克","D. 有感染的危险","E. 体液不足"],"answer":"正确答案：E．体液不足","correct":["E"],"source":"教材第1—2页","paper":"青岛大学2012｜单项选择题"},{"id":"ch01-exam-9","title":"关于护理程序，下列哪几项是正确的？","topic":"护理程序","options":["A. 执行护理程序时，需用多学科的知识","B. 护理程序只适合于医院","C. 把病人作为一个整体，考虑其生理、心理、社会方面的需求","D. 从病人入院时开始评估、诊断、计划、实施，至病人出院时评价后结束","E. 护理程序必须由护士独立执行"],"answer":"正确答案：A．执行护理程序时，需用多学科的知识；C．把病人作为一个整体，考虑其生理、心理、社会方面的需求","correct":["A","C"],"source":"教材第3—4页","paper":"青岛大学2013｜多项选择题"},{"id":"ch01-exam-10","title":"下列有关护理诊断排序的说法正确的是","topic":"课程定位","options":["A. 对于某个病人来说，护理诊断的先后顺序应是固定不变的","B. 现存的护理诊断一定排在有危险的护理诊断之前","C. 一个病人的首优问题只有一个","D. 护士可参照马斯洛需要层次学说排序","E. 必须先解决首优问题，然后再解决中优问题"],"answer":"正确答案：D．护士可参照马斯洛需要层次学说排序","correct":["D"],"source":"教材第1—2页","paper":"四川大学2011｜单项选择题"}]},{"id":"ch02","number":2,"title":"环境","page":"ch02-environment.html","lab":"ch02-learning-lab.html","core":[{"id":"ch02-core-1","title":"环境与健康","answer":"自然、社会和治疗性环境共同影响患者的安全、舒适和恢复。","reason":"具体考法：题干常要求指出环境因素怎样改变健康结局。","source":"教材第7—12页"},{"id":"ch02-core-2","title":"医院环境特点","answer":"服务对象复杂、专业分工协作，并以安全、舒适和治疗为目标。","reason":"具体考法：不能只答安静整洁，要写出专业性与安全性。","source":"教材第13—15页"},{"id":"ch02-core-3","title":"温湿度与通风","answer":"依据患者年龄、病情和治疗需要调节温度、湿度、光线与空气。","reason":"具体考法：数字题必须把数值和适用对象绑定。","source":"教材第15—18页"},{"id":"ch02-core-4","title":"噪声控制","answer":"减少声源、降低传播并调整人员行为，避免突然和持续刺激。","reason":"具体考法：问护理措施时要覆盖声源、设备、操作与沟通。","source":"教材第18—20页"},{"id":"ch02-core-5","title":"治疗性关系","answer":"尊重隐私、提供信息、鼓励参与，使患者在陌生环境中获得控制感。","reason":"具体考法：情境题常把物理环境与心理适应一起考。","source":"教材第20—22页"},{"id":"ch02-core-6","title":"地面安全分级","answer":"防滑等级必须与区域潮湿和行走风险匹配，不能只看外观是否干净。","reason":"具体考法：题干给卫生间、治疗室或走廊时，先判断湿滑风险再选材料和管理措施。","source":"教材第17页"},{"id":"ch02-core-7","title":"患者环境适应","answer":"入院后的陌生、失控和信息不足会加重焦虑，护士应介绍环境、说明规则并尊重隐私。","reason":"具体考法：环境题不只考温湿度，也会用患者不安考查治疗性环境。","source":"教材第20—22页"}],"numbers":[{"id":"ch02-number-1","title":"普通病室温度","answer":"18～22℃","condition":"一般成人病室","source":"教材第15—16页"},{"id":"ch02-number-2","title":"特殊病室温度","answer":"22～24℃","condition":"新生儿、老年人、产房及手术室等","source":"教材第15—16页"},{"id":"ch02-number-3","title":"病室相对湿度","answer":"50%～60%","condition":"一般病室","source":"教材第16页"},{"id":"ch02-number-4","title":"白天理想噪声","answer":"35～40 dB","condition":"病室环境管理","source":"教材第19页"},{"id":"ch02-number-5","title":"噪声干扰范围","answer":"50～60 dB","condition":"可影响休息和治疗","source":"教材第19页"},{"id":"ch02-number-6","title":"长期噪声伤害","answer":"≥90 dB","condition":"长期暴露可致听力和生理损害","source":"教材第19页"},{"id":"ch02-number-7","title":"突发强声损伤","answer":"≥120 dB","condition":"可造成永久性听力损害","source":"教材第19页"},{"id":"ch02-number-8","title":"地面防滑系数","answer":"＜0.50不安全；0.50～0.79安全；≥0.80很安全","condition":"医院区域按风险选择等级","source":"教材第17页"},{"id":"ch02-number-9","title":"急诊观察时间","answer":"一般3～7日","condition":"病情稳定后决定离院、入院或转诊","source":"教材第21页"}],"compare":[{"title":"温度过高/湿度过高","items":["A：影响散热、感到闷热","B：蒸发受限、潮湿不适","决定性区别：先看题干给的是温度还是湿度"]},{"title":"温度过低/湿度过低","items":["A：肌肉紧张、受凉","B：口干、咽痛、呼吸道不适","决定性区别：不要把两组表现互换"]},{"title":"安静/绝对无声","items":["A：降低不必要噪声","B：治疗和观察仍需正常进行","决定性区别：控制噪声不是停止必要沟通"]}],"questions":[{"id":"ch02-exam-1","title":"符合病人休养要求的环境是＝","topic":"病室相对湿度","options":["A. 中暑病人、室温保持在30℃","B. 儿科病房、室内温度宣23℃左右","C. 气管切开的病人、室内相对湿度40%左右","D. 产妇病室、应保暖、尽量不开窗"],"answer":"正确答案：B．儿科病房、室内温度宣23℃左右","correct":["B"],"source":"教材第16页","paper":"苏州大学2013｜单项选择题"},{"id":"ch02-exam-2","title":"有关病室温度的描述，正确的是","topic":"普通病室温度","options":["A. 室温过高不利于体力恢复","B. 室温过高干扰消化功能","C. 室温过高干扰呼吸功能","D. 室温过低可使患者肌肉紧张","E. 新生儿病房应保持在18-20℃"],"answer":"正确答案：D．室温过低可使患者肌肉紧张","correct":["D"],"source":"教材第15—16页","paper":"复旦大学2015｜单项选择题"},{"id":"ch02-exam-3","title":"某病人所居住的病室室温为31℃，相对湿度为70％，此环境对病人的影响是（）","topic":"病室相对湿度","options":["A. 闷热难受","B. 水分蒸发慢，散热增加","C. 水分蒸发快，散热增加","D. 咽喉疼痛","E. 肌肉紧张而产生不安"],"answer":"正确答案：A．闷热难受","correct":["A"],"source":"教材第16页","paper":"武汉科技大学2019｜单项选择题"},{"id":"ch02-exam-4","title":"某病房室温29℃,相对湿度80%,此时对患者的影响是","topic":"环境与健康","options":["A. 水分蒸发慢,散热增加","B. 水分蒸发快,散热减少","C. 咽喉干痛","D. 闷热难受","E. 肌肉紧张而产生不安"],"answer":"正确答案：D．闷热难受","correct":["D"],"source":"教材第7—12页","paper":"四川大学2014｜单项选择题"},{"id":"ch02-exam-5","title":"不适宜支气管哮喘患者康复的住院环境是","topic":"患者环境适应","options":["A. 室温在20℃左右","B. 病室光线明亮","C. 相对湿度为60%","D. 定时开窗通风","E. 室内放置鲜花"],"answer":"正确答案：E．室内放置鲜花","correct":["E"],"source":"教材第20—22页","paper":"青岛大学2012｜单项选择题"},{"id":"ch02-exam-6","title":"病室的相对湿度为70%时，患者可出现","topic":"病室相对湿度","options":["A. 肌肉紧张","B. 咽干、口渴","C. 闷热、不适","D. 头晕、倦怠","E. 发热、多汗"],"answer":"正确答案：C．闷热、不适","correct":["C"],"source":"教材第16页","paper":"青岛大学2011｜单项选择题"},{"id":"ch02-exam-7","title":"病室的相对湿度为70%时，病人可出现","topic":"病室相对湿度","options":["A. 肌肉紧张","B. 咽干、口渴","C. 闷热、不适","D. 头晕、倦怠","E. 发热、多汗"],"answer":"正确答案：C．闷热、不适","correct":["C"],"source":"教材第16页","paper":"杭州师范大学2013｜单项选择题"},{"id":"ch02-exam-8","title":"一般病室最适宜的温度和相对湿度为（）","topic":"病室相对湿度","options":["A. 12-14℃20%-30%","B. 14-15℃25%-35%","C. 16-18℃35%-45%","D. 18-22℃50%-60%","E. 22-24℃60%-70%"],"answer":"正确答案：D．18-22℃50%-60%","correct":["D"],"source":"教材第16页","paper":"河南大学2008｜单项选择题"},{"id":"ch02-exam-9","title":"病室适宜的相对湿度为","topic":"病室相对湿度","options":["A. 30%~40%","B. 40%~50%","C. 50%~60%","D. 60%~70%","E. 65%~75%"],"answer":"正确答案：C．50%~60%","correct":["C"],"source":"教材第16页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch02-exam-10","title":"病室温度过低的表现是","topic":"普通病室温度","options":["A. 空气干燥","B. 人体蒸发大量水分","C. 口舌干燥、咽痛、烦渴","D. 肌肉紧张、畏寒"],"answer":"正确答案：D．肌肉紧张、畏寒","correct":["D"],"source":"教材第15—16页","paper":"扬州大学2021｜单项选择题"}]},{"id":"ch03","number":3,"title":"预防与控制医院感染","page":"ch03-infection-control.html","lab":"ch03-learning-lab.html","core":[{"id":"ch03-core-1","title":"医院感染","answer":"结合入院前状态、潜伏期、诊疗活动和感染出现时间综合判断。","reason":"具体考法：48小时只是常用线索，不能替代完整诊断标准。","source":"教材第24—29页"},{"id":"ch03-core-2","title":"清洁消毒灭菌","answer":"先看目标层级和物品用途，再选择方法、参数与监测。","reason":"具体考法：高风险物品需要灭菌，方法正确还要过程合格。","source":"教材第30—44页"},{"id":"ch03-core-3","title":"手卫生","answer":"依据时机、可见污染和操作风险选择洗手或手消毒，手套不能替代。","reason":"具体考法：常考五时刻、方法选择和效果监测。","source":"教材第45—51页"},{"id":"ch03-core-4","title":"无菌技术","answer":"检查包装、日期和状态，划清无菌区，防止跨越、回流和接触污染。","reason":"具体考法：同一数字必须对应具体对象与起算时间。","source":"教材第51—60页"},{"id":"ch03-core-5","title":"隔离技术","answer":"标准预防用于所有患者，再按接触、飞沫或空气传播增加措施。","reason":"具体考法：先判断保护谁和传播途径，再选安置与防护。","source":"教材第60—74页"},{"id":"ch03-core-6","title":"高危险物品处理","answer":"进入无菌组织或血管系统的物品必须灭菌；接触完整黏膜者需高水平消毒。","reason":"具体考法：先按物品用途分危险等级，再选消毒灭菌方法。","source":"教材第30—31页"},{"id":"ch03-core-7","title":"标准预防与附加隔离","answer":"标准预防用于所有患者，明确传播途径后再叠加接触、飞沫或空气隔离。","reason":"具体考法：不是二选一；手套也不能替代手卫生。","source":"教材第45—74页"},{"id":"ch03-core-8","title":"无菌边界","answer":"跨越无菌区、手臂低于腰部、无菌物品受潮或接触非无菌面均视为污染。","reason":"具体考法：情境题要说出哪一步破坏了无菌边界。","source":"教材第51—60页"}],"numbers":[{"id":"ch03-number-1","title":"医院感染时间线索","answer":"入院≥48小时","condition":"无明确潜伏期时仍须结合完整诊断条件","source":"教材第25页"},{"id":"ch03-number-2","title":"下排气式压力蒸汽灭菌","answer":"121℃、102.8～122.9 kPa；器械20 min、敷料30 min","condition":"压力达到后计算时间","source":"教材第32页"},{"id":"ch03-number-3","title":"预真空压力蒸汽灭菌","answer":"132℃或134℃，维持4 min","condition":"按设备压力范围和装载要求执行","source":"教材第32页"},{"id":"ch03-number-4","title":"煮沸消毒","answer":"100℃，一般5～10 min；灭菌需≥15 min","condition":"海拔每升高300 m延长2 min","source":"教材第33页"},{"id":"ch03-number-5","title":"紫外线空气消毒","answer":"30 W灯距地面约2 m，照射≥30 min；≥1.5 W/m³","condition":"照射5～7 min后开始计时","source":"教材第33页"},{"id":"ch03-number-6","title":"紫外线表面消毒","answer":"距物品25～60 cm，照射20～30 min","condition":"物品摊开或悬挂扩大照射面","source":"教材第33页"},{"id":"ch03-number-7","title":"含氯消毒剂","answer":"400～700 mg/L作用30 min","condition":"常用环境物表消毒范围，现配现用","source":"教材第42—43页"},{"id":"ch03-number-8","title":"手卫生揉搓","answer":"≥15 s","condition":"洗手或卫生手消毒","source":"教材第48—49页"},{"id":"ch03-number-9","title":"卫生手消毒效果","answer":"≤10 CFU/cm²","condition":"卫生手消毒监测","source":"教材第46页"},{"id":"ch03-number-10","title":"外科手消毒效果","answer":"≤5 CFU/cm²","condition":"外科手消毒监测","source":"教材第46页"},{"id":"ch03-number-11","title":"无菌钳和无菌盘","answer":"有效4 h","condition":"分别注明启用或铺盘时间","source":"教材第53、57页"},{"id":"ch03-number-12","title":"开启无菌容器/回包","answer":"有效24 h","condition":"注明开启时间","source":"教材第54、56页"},{"id":"ch03-number-13","title":"灭菌包限重","answer":"器械包≤7 kg；敷料包≤5 kg","condition":"保证蒸汽穿透","source":"教材第32页"},{"id":"ch03-number-14","title":"高压灭菌冷却","answer":"一般＞30 min","condition":"干燥冷却后再卸载","source":"教材第32页"},{"id":"ch03-number-15","title":"煮沸增强剂","answer":"1%～2%碳酸氢钠使沸点约105℃","condition":"兼有防锈作用","source":"教材第33页"},{"id":"ch03-number-16","title":"紫外线灯强度","answer":"新灯≥90 μW/cm²；使用中≥70 μW/cm²","condition":"1 m处监测","source":"教材第33页"},{"id":"ch03-number-17","title":"紫外线灯寿命","answer":"累计约1000 h后复测或更换","condition":"记录使用时间","source":"教材第33页"},{"id":"ch03-number-18","title":"含氯溶液效期","answer":"一般≤24 h","condition":"密闭、避光保存","source":"教材第43页"},{"id":"ch03-number-19","title":"负压隔离病室","answer":"病室约−30 Pa、缓冲间约−15 Pa；换气≥6次/h","condition":"气流由清洁区流向污染区","source":"教材第61—62页"},{"id":"ch03-number-20","title":"同室隔离床距","answer":"≥1.1 m","condition":"同种病原体患者集中安置","source":"教材第62页"},{"id":"ch03-number-21","title":"无菌储存环境","answer":"温度＜24℃、湿度＜70%","condition":"离地≥20 cm、距顶＞50 cm、距墙＞5 cm","source":"教材第52页"}],"compare":[{"title":"清洁/消毒/灭菌","items":["A：去除污物","B：降低或杀灭病原微生物/杀灭全部微生物","决定性区别：先看目标层级"]},{"title":"标准预防/传播途径隔离","items":["A：所有患者均执行","B：已知风险后增加相应措施","决定性区别：两者叠加而非替代"]},{"title":"4小时/24小时","items":["A：持物钳、无菌盘","B：开启容器、回包","决定性区别：数字必须带对象"]}],"questions":[{"id":"ch03-exam-1","title":"患者男，28岁，因甲型肝炎入院，经积极治疗后痊愈出院。护士为其进行终末消毒处理，下列措施不妥的是","topic":"隔离技术","options":["A. 嘱患者更换清洁衣裤","B. 入院时的衣物经消毒处理后还给患者","C. 床单、被套及时送洗衣房","D. 室内空气用紫外线消毒","E. 病床、桌椅用消毒液擦拭"],"answer":"正确答案：C．床单、被套及时送洗衣房","correct":["C"],"source":"教材第60—74页","paper":"浙江中医药大学2020｜单项选择题"},{"id":"ch03-exam-2","title":"张女士，45岁，诊断为十二指肠溃殇，其排泄物消毒时适宜选择的方法是","topic":"清洁消毒灭菌","options":["A. 浸泡法","B. 擦拭法","C. 喷雾法","D. 熏蒸法","E. 干粉搅拌法"],"answer":"正确答案：E．干粉搅拌法","correct":["E"],"source":"教材第30—44页","paper":"扬州大学2021｜单项选择题"},{"id":"ch03-exam-3","title":"下列属于正确的吸痰方法是:","topic":"清洁消毒灭菌","options":["A. 严格无菌操作，吸痰导管每日更换一次","B. 应减少使用呼吸机患者的吸痰次数，吸痰前后给2分钟纯氧","C. 电动吸引器贮液瓶内的液体满后及时倾倒","D. 每次吸痰时间不超过15秒钟","E. 吸痰时应左右旋转，上下提拉，吸痰完毕后用生理盐水将导管冲洗干净，消毒后备用"],"answer":"正确答案：D．每次吸痰时间不超过15秒钟","correct":["D"],"source":"教材第30—44页","paper":"汕头大学2022｜单项选择题"},{"id":"ch03-exam-4","title":"下列关于医院感染概念的叙述，正确的是","topic":"医院感染","options":["A. 感染和发病必须同时发生","B. 住院患者和探视者是医院感染的主要对象","C. 患者出院后发生的感染也可能属于医院感染","D. 必须是患者在住院期间遭受且在住院期间发病的感染","E. 入院前已处于潜伏期、住院期间发病属于医院感染"],"answer":"正确答案：C．患者出院后发生的感染也可能属于医院感染","correct":["C"],"source":"教材第24—29页","paper":"浙江中医药大学2018｜单项选择题"},{"id":"ch03-exam-5","title":"浸润型肺结核患者入院后，下列哪项措施与预防疾病传播无关","topic":"隔离技术","options":["A. 接触患者时，戴口罩、帽子，穿隔离衣","B. 患者痰液用20%漂白粉溶液搅拌静置2小时后倒掉","C. 病室每日用紫外线照射进行空气消毒","D. 病室设纱门，室内喷洒灭虫药","E. 接触患者时，应遵守呼吸道隔离原则"],"answer":"正确答案：D．病室设纱门，室内喷洒灭虫药","correct":["D"],"source":"教材第60—74页","paper":"四川大学2013｜单项选择题"},{"id":"ch03-exam-6","title":"关于隔离原则，以下正确的是","topic":"无菌边界","options":["A. 帽子、口罩及隔离衣穿戴齐全的工作人员可在任何场所活动","B. 病人用过的物品应分为已被污染和未被污染两类","C. 护理人员穿隔离衣后必须尽快备齐用物","D. 已经落在地上的物品均视为污染物品","E. 传染源离开后所进行的消毒属随时消毒"],"answer":"正确答案：D．已经落在地上的物品均视为污染物品","correct":["D"],"source":"教材第51—60页","paper":"山西医科大学2012｜单项选择题"},{"id":"ch03-exam-7","title":"下列各项中，有致癌作用的化学消毒剂是","topic":"含氯消毒剂","options":["A. 过氧化氢","B. 乙醇","C. 福尔马林"],"answer":"正确答案：C．福尔马林","correct":["C"],"source":"教材第42—43页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch03-exam-8","title":"下列各项，可用于精密医疗器械消毒与灭菌的是OA.95%乙醇","topic":"清洁消毒灭菌","options":["A. 95%乙醇","B. 过氧乙酸","C. 福尔马林","D. 戊二醛"],"answer":"正确答案：D．戊二醛","correct":["D"],"source":"教材第30—44页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch03-exam-9","title":"下列各项中，需要执行呼吸道隔离的疾病是","topic":"清洁消毒灭菌","options":["A. 痢疾","B. 霍乱","C. 新型冠状病毒肺炎","D. 伤寒"],"answer":"正确答案：C．新型冠状病毒肺炎","correct":["C"],"source":"教材第30—44页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch03-exam-10","title":"对于乙肝表面抗原阳性病人手术后的器械，下列处理措施正确的是","topic":"清洁消毒灭菌","options":["A. 用0.2%的戊二醛浸泡1小时，再按普通器械处理","B. 用2%的过氧乙酸浸泡半小时，再按普通器械处理","C. 用0.2%的过氧乙酸浸泡1小时，再按普通器械处理","D. 用1%的84消毒液浸泡半小时，再按普通器械处理","E. 用0.2%的戊二醛浸泡1小时，再按普通器械处理"],"answer":"正确答案：B．用2%的过氧乙酸浸泡半小时，再按普通器械处理","correct":["B"],"source":"教材第30—44页","paper":"青岛大学2009｜单项选择题"}]},{"id":"ch04","number":4,"title":"入院与出院护理","page":"ch04-admission-discharge.html","lab":"ch04-learning-lab.html","core":[{"id":"ch04-core-1","title":"急危重患者先处理什么","answer":"先抢救和安置，身份及必要资料同步核对；手续可在病情允许后补办。","reason":"题干抓手：不能因完成流程而延误生命支持。","source":"教材第78—80页"},{"id":"ch04-core-2","title":"床单位怎么选","answer":"根据患者是否暂离、是否新入院，以及麻醉和手术方式选择床型。","reason":"题干抓手：术后返回优先想到麻醉床。","source":"教材第80—87页"},{"id":"ch04-core-3","title":"护理级别不是固定标签","answer":"护理级别由病情和自理能力共同决定，并随病情变化重新评估。","reason":"题干抓手：诊断或年龄相同，不代表护理级别相同。","source":"教材第87—89页"},{"id":"ch04-core-4","title":"卧位从目的和病情反推","answer":"先看意识、呼吸、循环和治疗目的，再核对禁忌、管路与安全条件。","reason":"题干抓手：病情变化后，答案也可能改变。","source":"教材第89—94页"},{"id":"ch04-core-5","title":"脊柱搬运先守住轴线","answer":"多人协调、统一口令，保持头颈躯干轴线，避免扭转和屈曲。","reason":"题干抓手：人数是表面，轴线稳定才是核心。","source":"教材第98—101页"},{"id":"ch04-core-6","title":"出院指导要能执行","answer":"评估准备度，完成用药、复诊和资料处理，并确认患者能够复述。","reason":"题干抓手：“已经讲过”不等于“患者会做”。","source":"教材第102—108页"}],"numbers":[{"id":"ch04-number-1","title":"休克卧位","answer":"头胸抬高10°～20°，下肢抬高20°～30°","condition":"兼顾呼吸和回心血量","source":"教材第91页"},{"id":"ch04-number-2","title":"半坐卧位","answer":"床头30°～50°","condition":"心肺疾患、面颈胸腹盆腔术后等","source":"教材第90—91页"},{"id":"ch04-number-3","title":"端坐位","answer":"床头70°～80°","condition":"严重呼吸困难、急性肺水肿","source":"教材第91页"},{"id":"ch04-number-4","title":"头低足高位","answer":"床尾抬高15～30 cm","condition":"按治疗目的选择并注意禁忌","source":"教材第92页"},{"id":"ch04-number-5","title":"头高足低位","answer":"床头抬高15°～30°","condition":"颅脑术后等降低颅内压情境","source":"教材第93页"},{"id":"ch04-number-6","title":"膝胸卧位","answer":"每次≤15 min","condition":"检查、治疗或矫正胎位","source":"教材第93页"},{"id":"ch04-number-7","title":"麻醉床保护垫位置","answer":"上缘距床头45～50 cm","condition":"腹部手术返回时保护床单位","source":"教材第84页"},{"id":"ch04-number-8","title":"搬运脊柱损伤者","answer":"通常4人搬运","condition":"保持头颈躯干轴线稳定","source":"教材第100—101页"}],"compare":[{"title":"备用床/暂空床","items":["A：接收新患者","B：供暂离床患者或新入院患者使用","决定性区别：看是否有人正在使用床位"]},{"title":"麻醉床/暂空床","items":["A：接收麻醉术后患者并便于抢救","B：保持病室整洁等待患者","决定性区别：看是否术后返回"]},{"title":"被动卧位/被迫卧位","items":["A：不能自行调整","B：为减轻痛苦主动采取特定姿势","决定性区别：能否自主是关键"]}],"questions":[{"id":"ch04-exam-1","title":"患者，男性，35岁，与人冲突时被击打腹部已2天，主诉腹痛，入院查体：全腹压痛、反跳痛、肌紧张，腹部膨隆，肠鸣音减弱，白细胞计数30×109/L，诊断为急性弥漫性化脓性腹膜炎。入院后行剖腹探查术，生命体征稳定，护士应为其安置:","topic":"半坐卧位","options":["A. 膝胸卧位","B. 健侧卧位","C. 患侧卧位","D. 平卧位","E. 半坐卧位"],"answer":"正确答案：E．半坐卧位","correct":["E"],"source":"教材第90—91页","paper":"汕头大学2022｜单项选择题"},{"id":"ch04-exam-2","title":"患者，男性，56岁，诊断为支气管扩张，喀血100mL后突然出现胸闷气促、张口瞪目、两手乱抓、大汗淋漓、牙关紧闭。此时患者应取:","topic":"头低足高位","options":["A. 头低足高位，头偏向一侧","B. 去枕平卧位","C. 平卧位，头偏向一侧","D. 端坐位","E. 患侧卧位"],"answer":"正确答案：A．头低足高位，头偏向一侧","correct":["A"],"source":"教材第92页","paper":"汕头大学2022｜单项选择题"},{"id":"ch04-exam-3","title":"患者赵某，男，33岁，因车祸致脾破裂急诊入院，现胸闷、气促、出冷汗、脉细速，血压68/50mmHg。护士应立即为其安置的体位是","topic":"中凹卧位","options":["A. 去枕平卧位","B. 中凹卧位","C. 头低脚高位","D. 半坐卧位"],"answer":"正确答案：B．中凹卧位","correct":["B"],"source":"教材第90—91页","paper":"复旦大学2017｜单项选择题"},{"id":"ch04-exam-4","title":"张女士，27岁，孕9个月，阴道无诱因流水2h急诊入院，诊断为胎膜早破，此患者应采取的卧位是:","topic":"头低足高位","options":["A. 头高脚低位","B. 去枕平卧位","C. 头低脚高位","D. 仰卧屈膝位","E. 膝胸卧位"],"answer":"正确答案：C．头低脚高位","correct":["C"],"source":"教材第93页","paper":"河南科技大学2020｜单项选择题"},{"id":"ch04-exam-5","title":"做膀胱镜检查的病人应采取的体位是（）","topic":"截石位","options":["A. 膝胸卧位","B. 去枕仰卧位","C. 头低足高位","D. 截石位","E. 俯卧位"],"answer":"正确答案：D．截石位","correct":["D"],"source":"教材第93页","paper":"暨南大学2021｜单项选择题"},{"id":"ch04-exam-6","title":"感染性腹膜炎术后取半坐卧位主要目的是","topic":"半坐卧位","options":["A. 利于呼吸","B. 减轻切口缝合处的张力，避免疼痛","C. 促使感染局限，减少全身中毒反应","D. 减少局部出血"],"answer":"正确答案：C．促使感染局限，减少全身中毒反应","correct":["C"],"source":"教材第90—91页","paper":"湖州师范学院2018｜单项选择题"},{"id":"ch04-exam-7","title":"关于半坐卧位，正确的是","topic":"半坐卧位","options":["A. 摇起床头≥60°","B. 适用于面部及颈部手术患者，减少局部出血","C. 对于呼吸困难患者，下肢屈膝的目的是为了使回心血量增加","D. 对于腹部手术后的患者，采取半卧位可增加腹部切口处的张力","E. 盆腔炎患者，可使炎症扩散"],"answer":"正确答案：B．适用于面部及颈部手术患者，减少局部出血","correct":["B"],"source":"教材第90—91页","paper":"暨南大学2011｜单项选择题"},{"id":"ch04-exam-8","title":"患者朱某，因颈椎骨折入院，在对其进行搬运的过程中，应注意","topic":"脊柱搬运原则","options":["A. 可采用三人搬运法","B. 可采用四人搬运法","C. 保持头部处于中立位","D. 上下坡时，患者头部应位于低处","E. 头颈两侧用衣物或沙袋加以固定"],"answer":"正确答案：B．可采用四人搬运法；C．保持头部处于中立位；E．头颈两侧用衣物或沙袋加以固定","correct":["B","C","E"],"source":"教材第98—101页","paper":"四川大学2011｜多项选择题"},{"id":"ch04-exam-9","title":"在输液过程出现呼吸困难、咳嗽、咳血性泡沫痰，下列处理措施哪项正确","topic":"端坐位","options":["A. 继续输液，减慢滴速－","B. 置病人于端坐位，两腿下垂","C. 持续低流量吸氧","D. 给予缩血管药物","E. 四肢加压以阻断动脉血流"],"answer":"正确答案：B．置病人于端坐位，两腿下垂","correct":["B"],"source":"教材第91页","paper":"杭州师范大学2020｜单项选择题"},{"id":"ch04-exam-10","title":"在输液过程中，发生急性肺水肿，应让病人取端坐位，两腿下垂，其作用是（）","topic":"端坐位","options":["A. 减少回心血量，减轻心脏负担","B. 改善呼吸","C. 减轻组织水肿","D. 改善血液循环，减轻缺氧","E. 减轻咳嗽症状"],"answer":"正确答案：A．减少回心血量，减轻心脏负担","correct":["A"],"source":"教材第91页","paper":"河南大学2008｜单项选择题"}]},{"id":"ch05","number":5,"title":"患者的安全与护士的职业防护","page":"ch05-safety-occupational-protection.html","lab":"ch05-learning-lab.html","core":[{"id":"ch05-core-1","title":"患者安全评估","answer":"结合年龄、意识、活动能力、药物、环境和既往事件判断风险。","reason":"具体考法：跌倒高危不是禁止活动，而是增加保护。","source":"教材第110—113页"},{"id":"ch05-core-2","title":"跌倒与坠床","answer":"改善环境、合理用药、呼叫可及、陪护与个体化活动指导共同预防。","reason":"具体考法：病例题常考夜间、如厕和体位性低血压。","source":"教材第113—118页"},{"id":"ch05-core-3","title":"约束保护","answer":"只有在必要且替代措施无效时使用，需告知、记录、观察循环与定时放松。","reason":"具体考法：不能把约束当惩罚或省事工具。","source":"教材第118—121页"},{"id":"ch05-core-4","title":"锐器伤处理","answer":"立即局部处理、报告、评估暴露源与暴露级别，按流程随访。","reason":"具体考法：先处理伤口，再报告评估，顺序常考。","source":"教材第124—129页"},{"id":"ch05-core-5","title":"职业防护","answer":"通过标准预防、工程控制、安全器具、个人防护和工作制度降低暴露。","reason":"具体考法：针帽回套和徒手分离针头是高风险操作。","source":"教材第121—130页"},{"id":"ch05-core-6","title":"约束使用边界","answer":"约束仅在必要且替代措施无效时使用，需解释、记录、持续观察并尽早解除。","reason":"具体考法：为管理方便或惩罚患者均不成立。","source":"教材第118—121页"},{"id":"ch05-core-7","title":"跌倒预防","answer":"改善环境、评估体位性低血压和药物、协助如厕与活动、把呼叫器放在可及处。","reason":"具体考法：高危不等于绝对卧床，保护性活动可避免失用。","source":"教材第113—118页"},{"id":"ch05-core-8","title":"锐器伤流程","answer":"立即冲洗和适当挤出血液，消毒、报告、评估暴露源与暴露级别，尽快启动预防并随访。","reason":"具体考法：常考先后顺序，不能先等化验结果再处理伤口。","source":"教材第124—129页"}],"numbers":[{"id":"ch05-number-1","title":"约束带松紧","answer":"可伸入1～2横指","condition":"固定后检查皮肤和末梢循环","source":"教材第119页"},{"id":"ch05-number-2","title":"约束观察","answer":"每15～30 min","condition":"观察颜色、温度、感觉和循环","source":"教材第119—120页"},{"id":"ch05-number-3","title":"约束松解","answer":"一般每2 h","condition":"松解时活动肢体并进行皮肤护理","source":"教材第120页"},{"id":"ch05-number-4","title":"乙肝暴露后免疫球蛋白","answer":"尽量在24 h内","condition":"结合免疫状态决定疫苗","source":"教材第125页"},{"id":"ch05-number-5","title":"乙肝疫苗程序","answer":"0、1、6个月","condition":"职业暴露后按免疫结果执行","source":"教材第125页"},{"id":"ch05-number-6","title":"HIV暴露后用药","answer":"尽量1～2 h内开始，疗程28 d","condition":"越早越好，不因等待检测而延误","source":"教材第126—127页"},{"id":"ch05-number-7","title":"HIV暴露随访","answer":"24 h、4周、8周、12周、6个月、12个月","condition":"按机构流程完成检测与咨询","source":"教材第127页"},{"id":"ch05-number-8","title":"跌倒高龄线索","answer":"年龄≥80岁","condition":"与既往跌倒、药物和活动能力共同评估","source":"教材第131页"},{"id":"ch05-number-9","title":"近期跌倒史","answer":"近6个月≥2次","condition":"提示高危","source":"教材第131页"},{"id":"ch05-number-10","title":"镇静药影响","answer":"使用后6 h内","condition":"加强活动协助与观察","source":"教材第131页"},{"id":"ch05-number-11","title":"肌力分级","answer":"0～5级；≤3级提示明显无力","condition":"与跌倒和转移风险联动","source":"教材第132页"},{"id":"ch05-number-12","title":"化疗防护手套","answer":"操作时约每30 min更换","condition":"污染或破损立即更换","source":"教材第128页"}],"compare":[{"title":"保护性约束/惩罚","items":["A：防止伤害且有明确指征","B：为管理方便限制患者","决定性区别：目的和必要性决定性质"]},{"title":"跌倒高危/绝对卧床","items":["A：增加监护和安全活动","B：完全禁止活动","决定性区别：预防不能制造失用风险"]},{"title":"伤口处理/暴露评估","items":["A：立即清洗与适当处置","B：报告后判断病原风险","决定性区别：两个步骤都不能缺"]}],"questions":[{"id":"ch05-exam-1","title":"患者女，56岁，因癫痫发作入院治疗。为防止坠床和自伤，经家属知情同意使用约束带；护理人员定时观察并放松约束带。该做法主要体现了保护具使用中的","topic":"约束保护","options":["A. 知’情同意","B. 短期使用","C. 随时评价","D. 循序渐进","E. 重点预防"],"answer":"正确答案：C．随时评价","correct":["C"],"source":"教材第118—121页","paper":"复旦大学2017｜单项选择题"},{"id":"ch05-exam-2","title":"患儿张某，左上肢烫伤，烫伤面积达10%，入院后经评估需使用保护具，下列哪项措施不正确:","topic":"约束保护","options":["A. 使用前需取得患者或家属的理解和同意","B. 属于保护性制动措施，只能短期使用","C. 将患者右上肢外展固定于身体右侧","D. 约束带下应置衬垫，且松紧适宜","E. 经常观察约束部位的皮肤颜色和温度"],"answer":"正确答案：C．将患者右上肢外展固定于身体右侧","correct":["C"],"source":"教材第118—121页","paper":"中南大学2019｜单项选择题"},{"id":"ch05-exam-3","title":"有关保护具的应用，错误的一项是","topic":"约束带松紧","options":["A. 使用前向病人家属解释清楚","B. 安置舒适的位置，常更换卧位","C. 扎紧约束带，定期按摩","D. 将枕头横立床头，以免头部撞伤","E. 床档必须两侧同时应用"],"answer":"正确答案：C．扎紧约束带，定期按摩","correct":["C"],"source":"教材第119页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch05-exam-4","title":"癫痫持续状态时确保病人安全的措施中，错误的是:","topic":"约束使用边界","options":["A. 取头低位或平卧头侧位","B. 由专人防护","C. 放置牙垫，防止舌咬伤","D. 放置床档，以防坠床","E. 发作时按压肢体，防止乱动"],"answer":"正确答案：E．发作时按压肢体，防止乱动","correct":["E"],"source":"教材第118—121页","paper":"中南大学2018｜单项选择题"},{"id":"ch05-exam-5","title":"关于保护具叙述正确的是（）","topic":"约束保护","options":["A. 腕部约束带主要限制患者躺下","B. 护士使用约束带时不需患者家属同意","C. 肩部与膝部约束带不可同时使用","D. 约束带定时松解，每2小时放松一次"],"answer":"正确答案：D．约束带定时松解，每2小时放松一次","correct":["D"],"source":"教材第118—121页","paper":"吉林大学2017｜单项选择题"},{"id":"ch05-exam-6","title":"关于保护具使用正确的是（）","topic":"约束保护","options":["A. 腕部约束带主要限制病人躺下","B. 护士使用约束带时不需病人家属同意","C. 肩部与膝部约束带不可同时使用","D. 约束带定时松解，每2小时放松一次"],"answer":"正确答案：D．约束带定时松解，每2小时放松一次","correct":["D"],"source":"教材第118—121页","paper":"吉林大学2018｜单项选择题"},{"id":"ch05-exam-7","title":"使用约束带时应重点观察的是","topic":"约束保护","options":["A. 衬垫是否移位","B. 约束部位局部皮肤颜色","C. 约束带是否牢靠","D. 患者的体位是否合适、舒适","E. 患者的神志"],"answer":"正确答案：B．约束部位局部皮肤颜色","correct":["B"],"source":"教材第118—121页","paper":"暨南大学2011｜单项选择题"},{"id":"ch05-exam-8","title":"以下哪种病人不需要应用保护具：","topic":"患者安全评估","options":["A. 高热病人","B. 昏迷病人","C. 躁动病人","D. 体温过低的病人","E. 谵妄的病人"],"answer":"正确答案：D．体温过低的病人","correct":["D"],"source":"教材第110—113页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch05-exam-9","title":"防止躁动不安患者坠床应使用","topic":"约束使用边界","options":["A. 床档","B. 肩部约束带","C. 膝部约束带","D. 腕部约束带","E. 踝部约束带"],"answer":"正确答案：A．床档","correct":["A"],"source":"教材第118—121页","paper":"山西医科大学2015｜单项选择题"},{"id":"ch05-exam-10","title":"使用保护具的注意事项","topic":"约束保护","options":["A. 只能短期使用","B. 用时肢体处于功能位","C. 约束带定期松解,约1次/1小时","D. 使用约束带,约1次/30分钟观察约束部位","E. 严格保护具适应证,维护病人自尊"],"answer":"正确答案：A．只能短期使用；B．用时肢体处于功能位；E．严格保护具适应证,维护病人自尊","correct":["A","B","E"],"source":"教材第118—121页","paper":"青岛大学2009｜多项选择题"}]},{"id":"ch06","number":6,"title":"患者的清洁卫生","page":"ch06-hygiene.html","lab":"ch06-learning-lab.html","core":[{"id":"ch06-core-1","title":"口腔护理","answer":"评估口腔状态和意识，按分泌物、感染或出血风险选择方法与溶液。","reason":"具体考法：昏迷患者禁忌漱口，棉球不可过湿。","source":"教材第134—139页"},{"id":"ch06-core-2","title":"头发护理","answer":"关注清洁、梳理、头虱处理及卧床患者安全。","reason":"具体考法：灭虱题要区分药物处理、包裹时间和物品消毒。","source":"教材第139—143页"},{"id":"ch06-core-3","title":"皮肤清洁","answer":"依据活动能力和病情选择淋浴、盆浴或床上擦浴，保护管路和隐私。","reason":"具体考法：饭后、病情不稳或特殊治疗时需调整。","source":"教材第143—151页"},{"id":"ch06-core-4","title":"压力性损伤","answer":"压力、剪切力、摩擦、潮湿和营养共同影响发生，重点是减压与皮肤管理。","reason":"具体考法：分期题看组织层次和创面特征，不能只看颜色。","source":"教材第151—159页"},{"id":"ch06-core-5","title":"会阴与晨晚间护理","answer":"按污染程度由清洁向污染方向操作，结合排泄、导管和舒适需要。","reason":"具体考法：题干常用留置导尿和失禁检验顺序。","source":"教材第159—166页"},{"id":"ch06-core-6","title":"漱口液选择","answer":"依据病原体、口腔pH和黏膜情况选择漱口液，浓度和适用对象必须一起记。","reason":"具体考法：真菌用碱性碳酸氢钠，铜绿假单胞菌用乙酸，厌氧菌用甲硝唑。","source":"教材第137页"},{"id":"ch06-core-7","title":"压力性损伤分期","answer":"从指压不褪色红斑到皮肤全层缺损、深部组织暴露，分期取决于可见组织层次。","reason":"具体考法：水疱与浅表破损多见于2期，焦痂覆盖时可能无法分期。","source":"教材第151—158页"},{"id":"ch06-core-8","title":"沐浴禁忌","answer":"病情不稳定、急性出血、严重呼吸困难或医嘱限制活动时不宜盆浴或淋浴。","reason":"具体考法：先评估能否耐受，再决定清洁方式。","source":"教材第145—147页"}],"numbers":[{"id":"ch06-number-1","title":"刷牙时间","answer":"每次≥3 min","condition":"掌握正确刷牙方法","source":"教材第135页"},{"id":"ch06-number-2","title":"特殊口腔护理","answer":"每日2～3次","condition":"危重、禁食、昏迷等患者","source":"教材第137页"},{"id":"ch06-number-3","title":"氯己定漱口液","answer":"0.02%","condition":"广谱抗菌","source":"教材第137页"},{"id":"ch06-number-4","title":"甲硝唑漱口液","answer":"0.08%","condition":"厌氧菌感染","source":"教材第137页"},{"id":"ch06-number-5","title":"过氧化氢漱口液","answer":"1%～3%","condition":"口腔感染、坏死组织和口臭","source":"教材第137页"},{"id":"ch06-number-6","title":"碳酸氢钠漱口液","answer":"1%～4%","condition":"真菌感染","source":"教材第137页"},{"id":"ch06-number-7","title":"乙酸溶液","answer":"0.1%","condition":"铜绿假单胞菌感染","source":"教材第137页"},{"id":"ch06-number-8","title":"机械通气口腔护理","answer":"每6～8 h；床头30°～45°","condition":"同时保持气囊压力20～30 cmH₂O","source":"教材第139页"},{"id":"ch06-number-9","title":"床上洗头水温","answer":"≤40℃","condition":"避免烫伤和不适","source":"教材第142页"},{"id":"ch06-number-10","title":"沐浴时间","answer":"约10 min；进食后1 h再沐浴","condition":"防疲劳和消化不适","source":"教材第145—147页"},{"id":"ch06-number-11","title":"压力性损伤翻身","answer":"一般每2 h，必要时每30 min","condition":"根据皮肤与受压风险个体化","source":"教材第156页"},{"id":"ch06-number-12","title":"硼酸漱口液","answer":"2%～3%","condition":"抑菌清洁","source":"教材第137页"},{"id":"ch06-number-13","title":"病室沐浴温度","answer":"通常≥22℃，体弱者约24℃","condition":"注意保暖和隐私","source":"教材第145—147页"},{"id":"ch06-number-14","title":"会阴冲洗水温","answer":"≤40℃","condition":"避免烫伤黏膜","source":"教材第161页"},{"id":"ch06-number-15","title":"百部灭虱","answer":"30%百部含酸乙醇浸剂","condition":"按操作要求包裹并彻底清洁","source":"教材第164—165页"}],"compare":[{"title":"剪切力/摩擦力","items":["A：组织层面相对移位","B：皮肤与床面直接摩擦","决定性区别：半卧位下滑常见剪切力"]},{"title":"不可分期/深部组织损伤","items":["A：创面被腐肉焦痂遮盖","B：深部组织颜色改变或血疱","决定性区别：能否看见基底是关键"]},{"title":"口腔清洁/漱口","items":["A：护士按顺序擦拭或冲洗","B：患者主动含漱","决定性区别：意识障碍患者不能自行漱口"]}],"questions":[{"id":"ch06-exam-1","title":"徐女士，67岁，因肺源性心脏病入院，现呼吸困难、痰液黏稠不易咳出；骶尾部有3cm×5cm的Ⅱ期压疮，并自诉全身无力。护士首先应解决的问题是","topic":"沐浴禁忌","options":["A. 清理呼吸道无效","B. 皮肤完整性受损","C. 语言沟通障碍","D. 活动无耐力","E. 心理问题"],"answer":"正确答案：A．清理呼吸道无效","correct":["A"],"source":"教材第145—147页","paper":"浙江中医药大学2018｜单项选择题"},{"id":"ch06-exam-2","title":"刘女士，67岁，患大叶性肺炎，高热昏迷10天，10天内给予大量抗生素治疗。近日发现其口腔黏膜破溃，创面上附着白色膜状物，拭去附着物可见创面轻微出血。为该病人口腔护理时可选用的漱口液是","topic":"口腔护理","options":["A. 生理盐水","B. 1％～4％碳酸氢钠溶液","C. 朵贝尔液","D. 0.02％呋喃西林溶液","E. 0.1％醋酸溶液"],"answer":"正确答案：B．1％～4％碳酸氢钠溶液","correct":["B"],"source":"教材第134—139页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch06-exam-3","title":"患者林某，男，68岁，因脑血管意外，昏迷已1月余，长期鼻饲，在护理操作中，下列护理措施不妥的是:","topic":"口腔护理","options":["A. 每日进行口腔护理2-3次","B. 鼻饲间隔时间不少于2hC.每次饲食前要检查胃管是否在胃内","D. 所有鼻饲物品每日应消毒一次","E. 胃管应每日更换，晩上拔出，次晨再由另一鼻孔插入"],"answer":"正确答案：E．胃管应每日更换，晩上拔出，次晨再由另一鼻孔插入","correct":["E"],"source":"教材第134—139页","paper":"中南大学2012｜单项选择题"},{"id":"ch06-exam-4","title":"患者，男，75岁，因肺心病失代偿期，入院护理体检：口唇发绀，呼吸困难，纳差，口腔溃疡，焦虑，应首先进行的护理措施是","topic":"口腔护理","options":["A. 心理护理，解除焦虑","B. 口腔护理，促进溃疡愈合","C. 加强饮食护理","D. 吸氧，缓解缺氧","E. 观察生命体征，及时记录"],"answer":"正确答案：D．吸氧，缓解缺氧","correct":["D"],"source":"教材第134—139页","paper":"山西医科大学2016｜单项选择题"},{"id":"ch06-exam-5","title":"某患者，女25岁，诊断为血小板减少性紫癜，检查居和口腔黏膜散在旅血点，轻触牙龈出血。该患者口腔护理应特别注意","topic":"口腔护理","options":["A. 动作轻稳勿损伤黏膜","B. 夹紧棉球防止遗留口腔","C. 蘸水不可过湿，以防呛咳","D. 擦拭时勿触及咽部以免恶心"],"answer":"正确答案：A．动作轻稳勿损伤黏膜","correct":["A"],"source":"教材第134—139页","paper":"武汉大学2014｜单项选择题"},{"id":"ch06-exam-6","title":"刘女士，36岁，患白血病住院治疗，护士为其进行口腔护理时，发现口腔黏膜有小块血痂。下列操作中不妥的是","topic":"口腔护理","options":["A. 将血痂皮去除，涂药","B. 观察舌苔情况","C. 轻轻地擦拭口腔各面","D. 用过氧化氢溶液漱口","E. 观察口腔黏膜变化"],"answer":"正确答案：A．将血痂皮去除，涂药","correct":["A"],"source":"教材第134—139页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch06-exam-7","title":"患者王某，36岁，因化脓性阑尾炎入院。术后伤口感染，持续高热2日，最高39℃。护士实施的护理措施中，不妥的是","topic":"口腔护理","options":["A. 密切观察病情变化","B. 测体温每天二次","C. 冰袋冷敷头部","D. 口腔护理"],"answer":"正确答案：B．测体温每天二次","correct":["B"],"source":"教材第134—139页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch06-exam-8","title":"患者女，32岁，因再生障碍性贫血入院。四肢皮肤散在瘀点、瘀斑，右颊部可见口腔溃疡，牙龈渗血。为有效预防感染，目前首先应采取的护理措施是","topic":"口腔护理","options":["A. 保持皮肤的干燥与清洁","B. 加强口腔护理","C. 定期进行会阴冲洗","D. 避免外出到人群聚集的地方"],"answer":"正确答案：B．加强口腔护理","correct":["B"],"source":"教材第134—139页","paper":"湖州师范学院2018｜单项选择题"},{"id":"ch06-exam-9","title":"为昏迷患者进行口腔护理时，以下操作不妥的是","topic":"口腔护理","options":["A. 先取下假牙","B. 将开口器从臼齿处放人，协助开口","C. 观察口腔情况后漱口","D. 棉球干湿适宜"],"answer":"正确答案：C．观察口腔情况后漱口","correct":["C"],"source":"教材第134—139页","paper":"杭州师范大学2016｜单项选择题"},{"id":"ch06-exam-10","title":"赵先生，臀部出现2cm*2cm的创面，呈表浅的开放性溃疡，基底粉红色，无坏死组织。根据卫生部《临床护理实践指南（2011版）》，该患者的压疮分期为（）","topic":"压力性损伤","options":["A. Ⅰ期","B. ‖期","C. Ⅲ期","D. Ⅳ期","E. 无可分期"],"answer":"正确答案：B．‖期","correct":["B"],"source":"教材第151—159页","paper":"杭州师范大学2018｜单项选择题"}]},{"id":"ch07","number":7,"title":"休息与活动","page":"ch07-rest-activity.html","lab":"ch07-learning-lab.html","core":[{"id":"ch07-core-1","title":"休息与睡眠","answer":"休息减少身心消耗，睡眠按周期维持生理和心理恢复。","reason":"具体考法：题干常用入睡困难、易醒和早醒区分睡眠问题。","source":"教材第168—175页"},{"id":"ch07-core-2","title":"睡眠周期","answer":"NREM与REM交替出现，各期生理表现和觉醒难度不同。","reason":"具体考法：深睡期、做梦期和生理变化是常考线索。","source":"教材第170—174页"},{"id":"ch07-core-3","title":"睡眠护理","answer":"从环境、习惯、疼痛、焦虑、用药和白天活动共同干预。","reason":"具体考法：不要把安眠药作为首选且唯一措施。","source":"教材第174—178页"},{"id":"ch07-core-4","title":"活动受限影响","answer":"长期不活动会累及皮肤、呼吸、循环、消化、泌尿和运动系统。","reason":"具体考法：问并发症时要跨系统作答。","source":"教材第179—182页"},{"id":"ch07-core-5","title":"协助活动","answer":"评估病情和肌力，按主动、被动及抗阻活动逐步增加强度。","reason":"具体考法：活动后出现胸闷、气促或生命体征异常应停止并复评。","source":"教材第182—187页"},{"id":"ch07-core-6","title":"NREM与REM","answer":"NREM侧重体力恢复，REM与记忆、情绪和梦境相关；夜间周期交替且后半夜REM增多。","reason":"具体考法：题目常用做梦、快速眼动和肌张力下降定位REM。","source":"教材第169—171页"},{"id":"ch07-core-7","title":"肌力与活动能力","answer":"肌力评价单一肌群收缩能力，活动能力分级评价完成日常活动所需帮助程度。","reason":"具体考法：不能把两个分级表混用。","source":"教材第181—182页"}],"numbers":[{"id":"ch07-number-1","title":"成人睡眠","answer":"约7～8 h/d","condition":"结合个体习惯与睡眠质量判断","source":"教材第172页"},{"id":"ch07-number-2","title":"睡眠周期","answer":"60～120 min，平均约90 min","condition":"每夜约4～6个周期","source":"教材第170页"},{"id":"ch07-number-3","title":"REM持续时间","answer":"约20～30 min","condition":"后半夜比例增加","source":"教材第170页"},{"id":"ch07-number-4","title":"夜间护理间隔","answer":"尽量避免＜90 min反复打断","condition":"集中治疗护理保护睡眠周期","source":"教材第176页"},{"id":"ch07-number-5","title":"关节活动","answer":"每个关节5～10次","condition":"动作缓慢，观察疼痛和耐受","source":"教材第184页"},{"id":"ch07-number-6","title":"肌力分级","answer":"0～5级","condition":"记录具体级别并观察动态变化","source":"教材第181页"},{"id":"ch07-number-7","title":"活动能力分级","answer":"0～4级","condition":"评估是否需要协助或完全依赖","source":"教材第182页"},{"id":"ch07-number-8","title":"SRSS量表","answer":"10项，每项1～5分，总分10～50","condition":"分数越高提示睡眠问题越明显","source":"教材第186页"}],"compare":[{"title":"休息/睡眠","items":["A：降低活动与紧张","B：周期性意识状态改变","决定性区别：休息不一定入睡"]},{"title":"主动/被动运动","items":["A：患者自主收缩肌肉","B：由他人移动关节","决定性区别：看力量来源"]},{"title":"失眠/睡眠过多","items":["A：入睡或维持困难","B：睡眠时间明显增多仍困倦","决定性区别：题干的时间和白天功能不同"]}],"questions":[{"id":"ch07-exam-1","title":"谭女士，46岁，行乳癌根治术后第2天，下列护理措施中，不正确的是","topic":"关节活动","options":["A. 患侧垫枕，抬高患肢","B. 保持伤口引流管通畅","C. 观察患侧肢端的血液循环","D. 指导病人做患侧肩关节活动","E. 禁止在患侧手臂测血压、输液"],"answer":"正确答案：D．指导病人做患侧肩关节活动","correct":["D"],"source":"教材第184页","paper":"杭州师范大学2020｜单项选择题"},{"id":"ch07-exam-2","title":"对关节脱位的病人不适宜采取的护理措施是：","topic":"关节活动","options":["A. 抬高患者的患肢，以利静脉回流，减轻肿胀","B. 髋关节脱位手法复位后，保持患髋屈曲、内收、内旋","C. 复位后关节出现疼痛时，可遵医嘱给予止痛剂","D. 向病人讲明复位后固定的重要性，防止习惯性脱位","E. 固定期间可进行肌肉舒缩及固定范围外的关节活动"],"answer":"正确答案：B．髋关节脱位手法复位后，保持患髋屈曲、内收、内旋","correct":["B"],"source":"教材第184页","paper":"四川大学2010｜单项选择题"},{"id":"ch07-exam-3","title":"肝性脑病昏迷期患者护理措施正确的是","topic":"睡眠护理","options":["A. 患者取仰卧位，头偏向一侧以防舌后坠阻塞呼吸道","B. 保持呼吸道通畅","C. 做好基础护理，防压疮","D. 尿潴留患者留置尿管，记录尿量、颜色、气味","E. 给患者做肢体的被动运动，防止静脉血栓形成"],"answer":"正确答案：A．患者取仰卧位，头偏向一侧以防舌后坠阻塞呼吸道；B．保持呼吸道通畅；C．做好基础护理，防压疮；D．尿潴留患者留置尿管，记录尿量、颜色、气味；E．给患者做肢体的被动运动，防止静脉血栓形成","correct":["A","B","C","D","E"],"source":"教材第174—178页","paper":"扬州大学2023｜多项选择题"},{"id":"ch07-exam-4","title":"下列关于发作性睡眠的描述，正确的是:","topic":"睡眠周期","options":["A. 发作性睡眠属于慢波睡眠障碍","B. 安静的环境不易发作","C. 发作时患者由清醒状态直接进入慢波睡眠","D. 发作性睡眠与正常睡眠不同","E. 猝倒症是最危险的并发症"],"answer":"正确答案：D．发作性睡眠与正常睡眠不同","correct":["D"],"source":"教材第170—174页","paper":"中南大学2017｜单项选择题"},{"id":"ch07-exam-5","title":"骨筋膜室综合征表现中哪项不对","topic":"活动受限影响","options":["A. 局部剧烈疼痛","B. 局部肿胀、严重压痛","C. 指或趾活动受限、感觉麻木","D. 局部及远端皮色苍白","E. 早期远端动脉搏动消失"],"answer":"正确答案：E．早期远端动脉搏动消失","correct":["E"],"source":"教材第179—182页","paper":"青岛大学2011｜单项选择题"},{"id":"ch07-exam-6","title":"刘先生，50岁，有吸烟史，咳嗽2个月，咯血或痰中带血2周，胸片示左肺上叶有1.5×2cm病灶，病人入院后入睡困难，易觉醒。引起病人睡眠不佳的主要原因是","topic":"睡眠周期","options":["A. 环境改变","B. 焦虑","C. 内分泌变化","D. 睡眠周期节律破坏","E. 病室不允许吸烟"],"answer":"正确答案：B．焦虑","correct":["B"],"source":"教材第170—174页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch07-exam-7","title":"患者金某，78岁．因颅脑损伤致昏迷，经积极脱水．降压治疗目前病情稳定，但意识不清．该患者住院期间因活动受限而致机体最大的危害是可能出现（）","topic":"活动受限影响","options":["A. 压疮","B. 肺部感染","C. 深静脉血栓形成","D. 体位性低血压"],"answer":"正确答案：A．压疮","correct":["A"],"source":"教材第179—182页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch07-exam-8","title":"患者，女，71岁，高血压病史10年，近半年来病入明显感觉体力活动受限，洗脸、刷牙即可引起呼吸困难、心悸，此病人目前心功能处于","topic":"活动受限影响","options":["A. 代偿期","B. Ⅰ级","C. Ⅱ级","D. Ⅲ级","E. Ⅳ级"],"answer":"正确答案：D．Ⅲ级","correct":["D"],"source":"教材第179—182页","paper":"青岛大学2009｜单项选择题"},{"id":"ch07-exam-9","title":"患者活动受限的原因有","topic":"睡眠护理","options":["A. 疼痛","B. 严重疾病","C. 神经功能受损","D. 某些医护措施的执行","E. 身体残疾"],"answer":"正确答案：A．疼痛；B．严重疾病；C．神经功能受损；D．某些医护措施的执行；E．身体残疾","correct":["A","B","C","D","E"],"source":"教材第174—178页","paper":"青岛大学2012｜多项选择题"},{"id":"ch07-exam-10","title":"病人王某，夜间睡眠时出现梦境，则可证明其睡眠进入:","topic":"睡眠周期","options":["A. NREM第I期","B. NREM第II期","C. NREM第III期","D. NREM第IV期","E. REM期"],"answer":"正确答案：E．REM期","correct":["E"],"source":"教材第170—174页","paper":"浙江大学2012｜单项选择题"}]},{"id":"ch08","number":8,"title":"医疗与护理文件","page":"ch08-documentation.html","lab":"ch08-learning-lab.html","core":[{"id":"ch08-core-1","title":"记录原则","answer":"及时、准确、完整、简要、清晰并使用规范术语，避免主观评价。","reason":"具体考法：错字处理和时间签名常以操作判断题出现。","source":"教材第189—191页"},{"id":"ch08-core-2","title":"体温单","answer":"集中呈现体温、脉搏、呼吸、血压、出入量等动态趋势。","reason":"具体考法：图表题先读时间轴，再辨符号和重测标记。","source":"教材第191—193页"},{"id":"ch08-core-3","title":"医嘱处理","answer":"先急后缓，临时医嘱及时执行，长期医嘱按规定转抄、核对与签名。","reason":"具体考法：口头医嘱仅用于抢救并需复述核对、事后补录。","source":"教材第193—196页"},{"id":"ch08-core-4","title":"特别护理记录","answer":"危重和病情变化患者按时间记录生命体征、出入量、措施及反应。","reason":"具体考法：记录不仅写做了什么，还要写患者反应。","source":"教材第196—197页"},{"id":"ch08-core-5","title":"交班报告","answer":"围绕新入、危重、手术、特殊检查和待完成事项突出变化与风险。","reason":"具体考法：交班不是复制整份病历，而是保证连续照护。","source":"教材第197—204页"},{"id":"ch08-core-6","title":"医嘱种类","answer":"长期医嘱持续有效，临时医嘱通常24小时内执行一次，备用医嘱按条件执行。","reason":"具体考法：先看有效时间和是否需重复执行。","source":"教材第194页"},{"id":"ch08-core-7","title":"口头医嘱","answer":"仅抢救等紧急情况下使用；护士复述，双方确认，执行后保留安瓿并及时补记。","reason":"具体考法：关键是复述核对和追溯，不是机械拒绝。","source":"教材第195页"},{"id":"ch08-core-8","title":"体温单符号","answer":"口温、腋温、肛温和脉搏使用不同符号；脉搏短绌需同时记录心率和脉率。","reason":"具体考法：先辨测量项目再连线，不能混符号。","source":"教材第192—193页"}],"numbers":[{"id":"ch08-number-1","title":"临时备用医嘱SOS","answer":"有效12 h","condition":"未执行即失效","source":"教材第194页"},{"id":"ch08-number-2","title":"长期备用医嘱PRN","answer":"有效时间＞24 h","condition":"按需要执行并记录","source":"教材第194页"},{"id":"ch08-number-3","title":"术后日数","answer":"手术次日为术后第1日，连续记录至第14日","condition":"体温单专用记录","source":"教材第192页"},{"id":"ch08-number-4","title":"体温单高温线","answer":"40～42℃","condition":"填写入院、转科、手术、分娩、死亡等事件","source":"教材第192—193页"},{"id":"ch08-number-5","title":"体温格值","answer":"每小格0.2℃","condition":"按测量部位符号绘制","source":"教材第193页"},{"id":"ch08-number-6","title":"低体温记录","answer":"体温＜35℃写“不升”","condition":"用蓝笔在相应时间纵格内记录","source":"教材第193页"},{"id":"ch08-number-7","title":"抢救口头医嘱补录","answer":"抢救结束后及时补记","condition":"执行前复述核对并保留空安瓿","source":"教材第195页"}],"compare":[{"title":"prn/sos","items":["A：长期备用、可重复","B：临时备用、限定时间一次","决定性区别：看有效期和能否重复"]},{"title":"长期医嘱/临时医嘱","items":["A：有效24小时以上","B：通常24小时内执行一次","决定性区别：不是按医嘱长短来猜"]},{"title":"病程事实/主观评价","items":["A：可观察可测量资料","B：带情绪或推测的判断","决定性区别：记录必须有依据"]}],"questions":[{"id":"ch08-exam-1","title":"患者王某，肺癌晚期，自述疼痛难忍，难以入睡。医生给患者开出以下医嘱：哌替啶50mgimq6hprn。下列说法正确的是","topic":"医嘱种类","options":["A. 有效时间在24小时以内","B. 过期未执行则失效，护士用红笔在医嘱栏内写“未用”","C. 自医生开写医嘱起12小时内有效","D. 每次执行后，在临时医嘱单内记录执行时间并签全名","E. 应在短时间内执行"],"answer":"正确答案：D．每次执行后，在临时医嘱单内记录执行时间并签全名","correct":["D"],"source":"教材第194页","paper":"四川大学2013｜单项选择题"},{"id":"ch08-exam-2","title":"下列有关医疗与护理文件的管理描述，符合管理要求的是（）","topic":"特别护理记录","options":["A. 患者不得复印医嘱单、医生查房记录单","B. 患者及家属有需要时，可以进入护理站翻阅自己的病例资料","C. 患者出院后，护理记录单必须随病例送病案室保存2年","D. 医疗与护理文件按规定放置，用后必须放回原处","E. 发生医疗事故纠纷时，封存的病历资料不可以是复印件"],"answer":"正确答案：D．医疗与护理文件按规定放置，用后必须放回原处","correct":["D"],"source":"教材第196—197页","paper":"暨南大学2019｜单项选择题"},{"id":"ch08-exam-3","title":"下列有关护理工作中的法律问题处理正确的是","topic":"口头医嘱","options":["A. 当护士发现医嘱有明显的问题时，可拒绝执行，但无权向医生提出质疑","B. 当护士发现医嘱有问题时仍执行时，由此造成的后果主要由医生承担","C. 护士如果利用工作之便盗卖吗啡等麻醉药品则不属犯法但需受行政处分","D. 护士在抢救病人时可以执行口头医嘱","E. 护生在执业护士的督导下，发生差错事故，由本人和带教护士共同承担法律责任"],"answer":"正确答案：D．护士在抢救病人时可以执行口头医嘱","correct":["D"],"source":"教材第195页","paper":"山西医科大学2012｜单项选择题"},{"id":"ch08-exam-4","title":"患者出院时间正确的记录方法是：","topic":"体温单","options":["A. 用红色钢笔竖写出院时间在当日体温单相应时间的40℃以下","B. 用红色铅笔竖写出院时间在当日体温单相应时间的40℃以下","C. 用红色钢笔竖写出院时间在当日体温单相应时间的40-42℃之间","D. 用红色铅笔竖写出院时间在当日体温单相应时间的40-42℃之间"],"answer":"正确答案：C．用红色钢笔竖写出院时间在当日体温单相应时间的40-42℃之间","correct":["C"],"source":"教材第191—193页","paper":"哈尔滨医科大学2013｜单项选择题"},{"id":"ch08-exam-5","title":"患者，即将行胃大部切除术，术前医嘱:阿托品0.5mgHst,护士首先应做的是","topic":"交班报告","options":["A. 将其转抄至长期医嘱单上","B. 将其转抄至临时医嘱单和治疗单上","C. 在该项医嘱前划蓝钢笔“”标记","D. 即刻给患者皮下注射阿托品0.5mg","E. 转抄至交班报告上，以便下一班护士查阅"],"answer":"正确答案：D．即刻给患者皮下注射阿托品0.5mg","correct":["D"],"source":"教材第197—204页","paper":"江南大学2019｜单项选择题"},{"id":"ch08-exam-6","title":"病区交班报告最先书写的是","topic":"交班报告","options":["A. 严重休克患者","B. 高热患者","C. 新入院患者","D. 转出患者","E. 阑尾术后患者"],"answer":"正确答案：D．转出患者","correct":["D"],"source":"教材第197—204页","paper":"复旦大学2016｜单项选择题"},{"id":"ch08-exam-7","title":"执行口头医嘱正确的做法是:","topic":"口头医嘱","options":["A. 一般情况下不执行口头医嘱","B. 在抢救或手术过程中可执行","C. 护士必须向医生复述一遍","D. 双方确认无误后方可执行","E. 事后及时补写在抢救记录单上"],"answer":"正确答案：A．一般情况下不执行口头医嘱；B．在抢救或手术过程中可执行；C．护士必须向医生复述一遍；D．双方确认无误后方可执行；E．事后及时补写在抢救记录单上","correct":["A","B","C","D","E"],"source":"教材第195页","paper":"浙江大学2011｜多项选择题"},{"id":"ch08-exam-8","title":"病区交班报告记录的顺序，首先是","topic":"交班报告","options":["A. 危重患者","B. 手术患者","C. 死亡患者","D. 新入院患者","E. 离开病区的患者"],"answer":"正确答案：E．离开病区的患者","correct":["E"],"source":"教材第197—204页","paper":"山西医科大学2011｜单项选择题"},{"id":"ch08-exam-9","title":"实施口头医嘱时做法不妥的是","topic":"口头医嘱","options":["A. 一般情况下不执行","B. 抢救病人时可执行","C. 执行后需补写医嘱","D. 手术中可执行","E. 护士听清后立即执行"],"answer":"正确答案：E．护士听清后立即执行","correct":["E"],"source":"教材第195页","paper":"青岛大学2011｜单项选择题"},{"id":"ch08-exam-10","title":"因抢救危急病人，未能及时书写护理记录，应在抢救结束后（）小时据实补记","topic":"抢救口头医嘱补录","options":["A. 2小时","B. 3小时","C. 4小时","D. 6小时","E. 8小时"],"answer":"正确答案：D．6小时","correct":["D"],"source":"教材第195页","paper":"陕西中医药大学2008-2009｜单项选择题"}]},{"id":"ch09","number":9,"title":"生命体征的评估与护理","page":"ch09-vital-signs.html","lab":"ch09-learning-lab.html","core":[{"id":"ch09-core-1","title":"体温","answer":"选择合适部位，排除活动、进食和局部因素，结合热型与伴随症状判断。","reason":"具体考法：测量部位、时间和禁忌经常组合命题。","source":"教材第206—215页"},{"id":"ch09-core-2","title":"脉搏","answer":"观察频率、节律、强弱和动脉壁状态，必要时与心率比较。","reason":"具体考法：脉搏短绌需两名护士同时测心率和脉率。","source":"教材第215—219页"},{"id":"ch09-core-3","title":"血压","answer":"袖带尺寸、肢体位置、放气速度和患者状态都会影响读数。","reason":"具体考法：误差题要求指出读数偏高还是偏低。","source":"教材第219—226页"},{"id":"ch09-core-4","title":"呼吸","answer":"患者不知情时连续观察频率、节律、深浅、声音和困难程度。","reason":"具体考法：异常呼吸要同时联系病因和护理。","source":"教材第226—230页"},{"id":"ch09-core-5","title":"氧疗","answer":"先判断低氧和病因，选择装置、流量与湿化，持续评价效果和不良反应。","reason":"具体考法：慢性Ⅱ型呼衰常考低流量、低浓度持续给氧。","source":"教材第230—239页"},{"id":"ch09-core-6","title":"测温禁忌","answer":"婴幼儿、昏迷、口腔疾患等不宜口温；腹泻、直肠术后等不宜肛温；腋下创伤或手术侧需避开。","reason":"具体考法：测量部位由患者条件决定，不是只选最方便。","source":"教材第211—213页"},{"id":"ch09-core-7","title":"脉搏短绌","answer":"心率大于脉率时由两人同时测量1分钟，记录心率/脉率。","reason":"具体考法：常见于心房颤动，不能分别在不同时间测。","source":"教材第217页"},{"id":"ch09-core-8","title":"血压误差方向","answer":"袖带过窄、缠得过松或手臂低于心脏可使读数偏高；相反条件可偏低。","reason":"具体考法：先看袖带、手臂、视线和放气速度再判断误差方向。","source":"教材第223—225页"},{"id":"ch09-core-9","title":"给氧安全","answer":"氧疗是用药，需核对装置、流量和目标，防火防油防震，观察疗效和二氧化碳潴留。","reason":"具体考法：Ⅱ型呼衰不能因低氧擅自调成高流量。","source":"教材第231—237页"}],"numbers":[{"id":"ch09-number-1","title":"正常口温","answer":"36.3～37.2℃","condition":"口腔舌下测量","source":"教材第207页"},{"id":"ch09-number-2","title":"正常腋温","answer":"36.0～37.0℃","condition":"腋窝紧贴皮肤","source":"教材第207页"},{"id":"ch09-number-3","title":"正常肛温","answer":"36.5～37.7℃","condition":"直肠测量","source":"教材第207页"},{"id":"ch09-number-4","title":"发热分度","answer":"37.3～38.0低热；38.1～39.0中热；39.1～41.0高热；＞41超高热","condition":"以口温为例","source":"教材第208页"},{"id":"ch09-number-5","title":"测温时间","answer":"口温、肛温3 min；腋温10 min","condition":"测量方法正确时使用","source":"教材第212—213页"},{"id":"ch09-number-6","title":"肛表插入","answer":"成人3～4 cm；婴儿1.25 cm；幼儿2.5 cm","condition":"避免损伤","source":"教材第213页"},{"id":"ch09-number-7","title":"运动进食后复测","answer":"休息30 min","condition":"排除短暂影响","source":"教材第212页"},{"id":"ch09-number-8","title":"冷疗后复测","answer":"30 min","condition":"观察体温变化","source":"教材第209页"},{"id":"ch09-number-9","title":"成人脉搏","answer":"60～100次/min","condition":"静息状态","source":"教材第216页"},{"id":"ch09-number-10","title":"成人呼吸","answer":"16～20次/min","condition":"静息状态","source":"教材第226页"},{"id":"ch09-number-11","title":"呼吸与脉搏","answer":"约1:4","condition":"成人正常参考","source":"教材第226页"},{"id":"ch09-number-12","title":"成人血压","answer":"收缩压90～139、舒张压60～89 mmHg","condition":"结合重复测量和危险因素判断","source":"教材第220页"},{"id":"ch09-number-13","title":"正常脉压","answer":"30～40 mmHg","condition":"收缩压减舒张压","source":"教材第220页"},{"id":"ch09-number-14","title":"袖带下缘","answer":"距肘窝2～3 cm","condition":"松紧可容一指","source":"教材第224页"},{"id":"ch09-number-15","title":"氧浓度估算","answer":"FiO₂≈21＋4×氧流量(L/min)","condition":"鼻导管低流量吸氧估算","source":"教材第232页"},{"id":"ch09-number-16","title":"氧气筒余压","answer":"至少保留0.5 MPa","condition":"防灰尘进入与再次充装爆炸风险","source":"教材第234页"},{"id":"ch09-number-17","title":"成人标准袖带","answer":"气囊长22～26 cm、宽约12 cm","condition":"常用于臂围25～35 cm","source":"教材第222、225页"},{"id":"ch09-number-18","title":"大号袖带","answer":"臂围＞32 cm考虑","condition":"过窄袖带可使读数偏高","source":"教材第225页"},{"id":"ch09-number-19","title":"鼻导管流量","answer":"1～5 L/min","condition":"常规低流量给氧","source":"教材第235页"},{"id":"ch09-number-20","title":"文丘里面罩","answer":"约2～15 L/min","condition":"按喷嘴准确给定氧浓度","source":"教材第235页"},{"id":"ch09-number-21","title":"高流量鼻导管","answer":"约8～80 L/min，FiO₂ 21%～100%","condition":"需加温加湿","source":"教材第236页"},{"id":"ch09-number-22","title":"氧中毒风险","answer":"吸入氧浓度＞60%且持续＞24 h","condition":"尽量用最低有效浓度","source":"教材第236页"},{"id":"ch09-number-23","title":"Ⅱ型呼衰氧疗","answer":"常用1～2 L/min持续低流量","condition":"同时观察意识、呼吸和血气","source":"教材第236页"}],"compare":[{"title":"体温上升期/高热持续期","items":["A：产热大于散热、畏寒寒战","B：产热与散热在较高水平平衡","决定性区别：有无寒战和皮肤表现"]},{"title":"脉搏短绌/心动过速","items":["A：心率大于脉率","B：脉搏频率整体增快","决定性区别：必须同时测心率脉率"]},{"title":"库斯莫尔呼吸/潮式呼吸","items":["A：深大规则","B：由浅慢到深快再变浅暂停","决定性区别：节律变化完全不同"]}],"questions":[{"id":"ch09-exam-1","title":"患者高某，女性，76岁。独住，因子女不孝而厌世服毒，邻居发现后将昏迷的老人送入医院救治。在不知老人服何毒物时，护士应采取的护理措施是","topic":"呼吸","options":["A. 禁忌洗胃,待查明毒物名称后再处理","B. 抽出胃内容物,再用温开水洗胃","C. 用生理盐水灌肠,减少毒物吸收","D. 鼻饲牛奶或蛋清水,以保护胃黏膜","E. 氧气吸入，待清醒后用催吐法排出毒物"],"answer":"正确答案：B．抽出胃内容物,再用温开水洗胃","correct":["B"],"source":"教材第226—230页","paper":"四川大学2012｜单项选择题"},{"id":"ch09-exam-2","title":"患者女性，68岁，慢性支气管炎5年，近日感冒后病情加重，夜间咳嗽频繁，痰量多。查体:神志清，口唇轻度紫钳，双肺呼吸音低，动脉血气分析:PaO₂85mmHg，PaCO₂45mmHg，经治疗后病情缓解，护士对其进行的健康教育中，不妥的是:","topic":"呼吸","options":["A. 做腹式呼吸加强膈肌运动","B. 避免吸入有害气体","C. 大风降温时避免室外活动","D. 长期家庭氧疗","E. 做大量行走，锻炼改善肺功能"],"answer":"正确答案：E．做大量行走，锻炼改善肺功能","correct":["E"],"source":"教材第226—230页","paper":"中南大学2018｜单项选择题"},{"id":"ch09-exam-3","title":"男性，60岁，因肺心病呼吸衰竭入院。入院查体：神志清晰，血气分析：PaO₂30mmHg，PaCO₂60mmHg。吸氧后神志不清，血气分析：PaO₂70mmHg，PaCO₂80mmHg.该患者病情恶化的原因最可能的是","topic":"呼吸","options":["A. 感染加重","B. 气道阻力增加","C. 氧疗不当","D. 心力衰竭加重","E. 周围循环衰竭"],"answer":"正确答案：C．氧疗不当","correct":["C"],"source":"教材第226—230页","paper":"山西医科大学2016｜单项选择题"},{"id":"ch09-exam-4","title":"男性，69岁，反复咳嗽、咳痰30余年，活动后气短12年。动脉血气分析示PaCO₂50mmHg，PaO₂45mmHg，能延长其寿命、防止肺动脉高压发展的最有效的家庭治疗是","topic":"氧疗","options":["A. 抗生素控制感染","B. 支气管舒张剂治疗","C. 吸入糖皮质激素","D. 呼吸机锻炼","E. 长期家庭氧疗"],"answer":"正确答案：E．长期家庭氧疗","correct":["E"],"source":"教材第230—239页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch09-exam-5","title":".付某，男，18岁，因游泳过程中不幸溺水，经同伴打捞上岸后见患者意识丧失，呼吸停止，大动脉搏动消失，皮肤青紫，抢救的首要步骤是","topic":"脉搏","options":["A. 立即给予氧气吸入","B. 立即给予呼吸兴奋剂","C. 立即让患者仰卧，人工呼吸","D. 立即进行胸外心脏按压迫／立即清理呼吸道"],"answer":"正确答案：D．立即进行胸外心脏按压迫／立即清理呼吸道","correct":["D"],"source":"教材第215—219页","paper":"中南大学2011｜单项选择题"},{"id":"ch09-exam-6","title":"患者林某，女，50岁。诊断为“菌痢”。护士测量体温时得知其5min前饮过开水，为此应:","topic":"体温","options":["A. 用冷开水漱口后立即测量","B. 参照上次测量值记录","C. 改测直肠温度","D. 暂停本次测量","E. 30分钟后再测口腔温度"],"answer":"正确答案：E．30分钟后再测口腔温度","correct":["E"],"source":"教材第206—215页","paper":"中南大学2018｜单项选择题"},{"id":"ch09-exam-7","title":"患者史某，女，50岁。持续昏迷，护士观察到其痰液粘稠致呼吸困难，下列处理不．妥．的是","topic":"呼吸","options":["A. 氧气吸入","B. 用力叩击胸壁脊柱，以利排痰","C. 必要时用吸引器吸痰","D. 帮助患者多翻身","E. 超声雾化吸入"],"answer":"正确答案：B．用力叩击胸壁脊柱，以利排痰","correct":["B"],"source":"教材第226—230页","paper":"扬州大学2023｜单项选择题"},{"id":"ch09-exam-8","title":"某患者，18岁，自幼有支气管哮喘病虫，今与同学到公园春游时突然哮喘发作，对此，主要的处理措施是","topic":"血压","options":["A. 休息","B. 氧气吸入","C. 使用糖皮质激素","D. 使用自2受体激动剂","E. 做好心理护理"],"answer":"正确答案：D．使用自2受体激动剂","correct":["D"],"source":"教材第219—226页","paper":"天津中医药大学2017｜单项选择题"},{"id":"ch09-exam-9","title":"甲状腺大部切除术后伤口内出血，引起呼吸困难，紧急措施应","topic":"呼吸","options":["A. 注射止血剂","B. 氧气吸入","C. 拆除缝线去除血块","D. 加压包扎"],"answer":"正确答案：C．拆除缝线去除血块","correct":["C"],"source":"教材第226—230页","paper":"暨南大学2012｜单项选择题"},{"id":"ch09-exam-10","title":"某肺心病病人，血气分析:动脉血氧分压45mmHg,动脉血二氧化碳分压75mmHg,应使用哪一种氧疗法:","topic":"氧疗","options":["A. 持续低流量、低浓度给氧","B. 持续高流量、高浓度给氧","C. 间歇低流量、低浓度给氧","D. 间歇高流量、高浓度给氧","E. 间歇高流量、酒精湿化给氧"],"answer":"正确答案：A．持续低流量、低浓度给氧","correct":["A"],"source":"教材第230—239页","paper":"浙江大学2012｜单项选择题"}]},{"id":"ch10","number":10,"title":"冷、热疗法","page":"ch10-heat-cold.html","lab":"ch10-learning-lab.html","core":[{"id":"ch10-core-1","title":"冷疗效应","answer":"使局部血管收缩、减轻充血出血和疼痛，并降低组织代谢。","reason":"具体考法：早期软组织损伤常考先冷后热。","source":"教材第241—243页"},{"id":"ch10-core-2","title":"热疗效应","answer":"扩张血管、促进循环、减轻慢性炎症和肌肉痉挛。","reason":"具体考法：急腹症未确诊、出血或软组织损伤早期禁热。","source":"教材第243—249页"},{"id":"ch10-core-3","title":"冷疗禁忌","answer":"血液循环障碍、组织损伤、对冷过敏及枕后耳廓阴囊心前区腹部足底等慎禁。","reason":"具体考法：题干常给部位让选是否可用冰袋。","source":"教材第243—249页"},{"id":"ch10-core-4","title":"热疗禁忌","answer":"未明确诊断的急腹症、面部危险三角区感染、出血和知觉障碍者需避免或慎用。","reason":"具体考法：禁忌题要说明热会加重什么风险。","source":"教材第249—254页"},{"id":"ch10-core-5","title":"安全观察","answer":"隔布保护，定时查看皮肤、循环和感觉，出现异常立即停止。","reason":"具体考法：意识或感觉障碍患者需更密切观察。","source":"教材第243—255页"},{"id":"ch10-core-6","title":"冷热疗共同边界","answer":"使用前评估皮肤感觉、循环、意识和治疗部位；过程中观察颜色、疼痛和全身反应。","reason":"具体考法：昏迷、感觉障碍和末梢循环差者最易发生损伤。","source":"教材第241—244页"}],"numbers":[{"id":"ch10-number-1","title":"冷热疗持续时间","answer":"一般20～30 min，间隔约1 h","condition":"防止继发效应和组织损伤","source":"教材第242页"},{"id":"ch10-number-2","title":"冰袋装量","answer":"约1/2～2/3满","condition":"排气并检查漏水","source":"教材第245页"},{"id":"ch10-number-3","title":"冰袋降温停用线","answer":"体温降至39℃以下","condition":"停用后30 min复测","source":"教材第245页"},{"id":"ch10-number-4","title":"冷湿敷","answer":"18～20℃，每3～5 min更换，共15～20 min","condition":"保持敷布低温","source":"教材第246页"},{"id":"ch10-number-5","title":"温水擦浴","answer":"32～34℃","condition":"高热物理降温","source":"教材第248页"},{"id":"ch10-number-6","title":"乙醇擦浴","answer":"25%～35%，约200～300 ml","condition":"禁擦胸前区、腹部、后颈和足底等","source":"教材第248页"},{"id":"ch10-number-7","title":"热水袋","answer":"一般60～70℃；老年、婴幼儿、昏迷等约50℃","condition":"装1/2～2/3满并加布套","source":"教材第250页"},{"id":"ch10-number-8","title":"热湿敷","answer":"50～60℃，每3～5 min更换","condition":"总时间依耐受控制","source":"教材第252页"},{"id":"ch10-number-9","title":"红外线灯","answer":"距患处30～50 cm，照射20～30 min","condition":"以温热舒适、皮肤粉红为宜","source":"教材第253页"},{"id":"ch10-number-10","title":"低温烫伤","answer":"可发生于43～60℃持续接触","condition":"感觉障碍和昏迷患者风险高","source":"教材第256页"}],"compare":[{"title":"急性损伤早期/48小时后","items":["A：冷疗减轻出血肿胀","B：热疗促进吸收","决定性区别：先看受伤时间"]},{"title":"热水袋普通患者/特殊患者","items":["A：60～70℃","B：昏迷、老年、婴幼儿等约50℃","决定性区别：感觉差更易烫伤"]},{"title":"冷疗停止/继续","items":["A：苍白青紫麻木立即停止","B：轻微凉感可继续观察","决定性区别：皮肤和主诉决定"]}],"questions":[{"id":"ch10-exam-1","title":"李阿姨，70岁，胆囊切除术后，感到畏寒，在足部使用热水袋时，发现局部皮肤出现潮红、疼痛，此时正确的处理是（）","topic":"热水袋","options":["A. 热水袋外再包一条毛巾后继续使用","B. 立即停用，局部用25%硫酸镁湿热敷","C. 立即停用，局部涂凡士林","D. 立即停用，局部涂90%乙醇","E. 热水袋中加凉水后继续使用"],"answer":"正确答案：C．立即停用，局部涂凡士林","correct":["C"],"source":"教材第250页","paper":"暨南大学2021｜单项选择题"},{"id":"ch10-exam-2","title":"刘先生，40岁，左前臂口度烧伤5天，目前局部创面温润、疼痛。可在局部进行的处理是","topic":"红外线灯","options":["A. 红外线照射，每次20-30分钟","B. 湿热敷，7.1<温40%-60%","C. 冷湿敷，促进炎症吸收","D. 放置热水袋，7.1<温60一70摄氏度"],"answer":"正确答案：A．红外线照射，每次20-30分钟","correct":["A"],"source":"教材第253页","paper":"武汉大学2014｜单项选择题"},{"id":"ch10-exam-3","title":"张某，女，38岁，突然感到腹痛难忍，面色苍白、出冷汗来院就诊，在医生未确诊之前，值班护士的处理方法不妥的是:","topic":"热水袋","options":["A. 立即通知医生","B. 测量生命体征","C. 给予热水袋止痛","D. 了解患者腹痛的原因","E. 准备急救物品"],"answer":"正确答案：C．给予热水袋止痛","correct":["C"],"source":"教材第250页","paper":"中南大学2012｜单项选择题"},{"id":"ch10-exam-4","title":"应用冷疗减轻疼痛的机制是","topic":"冷疗效应","options":["A. 减少局部血流，降低细菌的活力","B. 降低组织的新陈代谢","C. 收缩血管，降低肌肉组织的紧张性","D. 降低神经末梢的敏感性","E. 减慢血循环，减少对致痛物质的运输"],"answer":"正确答案：D．降低神经末梢的敏感性","correct":["D"],"source":"教材第241—243页","paper":"四川大学2013｜单项选择题"},{"id":"ch10-exam-5","title":"急诊科收治一患者张某，女，32岁，入院时剧烈腹痛，面色苍白，大汗淋漓，值班护士采取的措施哪项不妥：","topic":"热水袋","options":["A. 立即通知医生","B. 询问病史","C. 测生命体征","D. 置热水袋于腹部缓解疼痛","E. 安慰患者"],"answer":"正确答案：D．置热水袋于腹部缓解疼痛","correct":["D"],"source":"教材第250页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch10-exam-6","title":"刘小姐，25岁，左侧第二磨牙牙龈红肿，牙痛影响睡眠，最佳的护理指导是:","topic":"红外线灯","options":["A. 口含冰块","B. 口含温开水","C. 侧卧位面颊置热水袋","D. 侧卧位面颊置冰袋","E. 红外线照射"],"answer":"正确答案：A．口含冰块","correct":["A"],"source":"教材第253页","paper":"浙江大学2012｜单项选择题"},{"id":"ch10-exam-7","title":"扬某，女，55岁，甲状腺瘤术后，局部出血．疼痛，应采取下列哪项措施：","topic":"热水袋","options":["A. 局部冰袋冷敷","B. 局部湿热敷","C. 局部敷热水袋","D. 局部红外线灯照射","E. 中药热敷"],"answer":"正确答案：A．局部冰袋冷敷","correct":["A"],"source":"教材第250页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch10-exam-8","title":"学生刘某，男性，18岁。篮球比赛时不慎踝部扭伤，应立即给予","topic":"冷湿敷","options":["A. 局部按摩","B. 局部冷湿敷","C. 红外线照射","D. 放置热水袋","E. 松节油涂擦"],"answer":"正确答案：B．局部冷湿敷","correct":["B"],"source":"教材第246页","paper":"四川大学2012｜单项选择题"},{"id":"ch10-exam-9","title":"患者左侧踝关节扭伤，为防止皮下出血与肿胀，早期应","topic":"冷湿敷","options":["A. 局部按摩","B. 冷热交替敷","C. 冷湿敷","D. 热湿敷"],"answer":"正确答案：C．冷湿敷","correct":["C"],"source":"教材第246页","paper":"四川大学2014｜单项选择题"},{"id":"ch10-exam-10","title":"病人赵某，因“上呼吸道感染”入院，体温40℃，神志清楚，护士为她温水擦浴，不正确的是","topic":"温水擦浴","options":["A. 头部冰袋冷敷，足底放热水袋","B. 血管丰富处适当延长时间","C. 心前区、腹部、足底禁止擦浴","D. 观察患者，发现其面色苍白、发冷，应加快擦浴速度","E. 擦浴结束后，体温降到39℃以下可取下冰袋"],"answer":"正确答案：D．观察患者，发现其面色苍白、发冷，应加快擦浴速度","correct":["D"],"source":"教材第248页","paper":"山西医科大学2016｜单项选择题"}]},{"id":"ch11","number":11,"title":"饮食与营养","page":"ch11-nutrition.html","lab":"ch11-learning-lab.html","core":[{"id":"ch11-core-1","title":"营养评估","answer":"结合体重变化、摄入、疾病消耗、实验室资料和功能状态判断。","reason":"具体考法：单次体重不能替代连续趋势和摄入评估。","source":"教材第258—263页"},{"id":"ch11-core-2","title":"基本饮食","answer":"普通、软质、半流质和流质饮食按咀嚼吞咽及消化能力选择。","reason":"具体考法：病例题常用术后阶段和消化功能选饮食。","source":"教材第263—265页"},{"id":"ch11-core-3","title":"治疗饮食","answer":"按疾病需要调整能量、蛋白质、脂肪、盐、纤维或其他成分。","reason":"具体考法：选择饮食时必须与病情目标配对。","source":"教材第264—266页"},{"id":"ch11-core-4","title":"一般饮食护理","answer":"营造进食环境，协助体位和餐前准备，记录摄入并观察反应。","reason":"具体考法：进食困难先评估原因和吞咽安全。","source":"教材第266—269页"},{"id":"ch11-core-5","title":"鼻饲","answer":"确认管位、采用合适体位和温度，少量分次，保持通畅并防误吸。","reason":"具体考法：昏迷患者插管和每次喂食前管位确认常考。","source":"教材第269—275页"},{"id":"ch11-core-6","title":"治疗饮食选择","answer":"治疗饮食不是只背名称，要根据疾病限制或增加能量、蛋白质、脂肪、钠和钾。","reason":"具体考法：题干给肾衰、肝病、高血压或高代谢时先找需要限制与需要补充的营养素。","source":"教材第264—266页"},{"id":"ch11-core-7","title":"鼻饲前核对","answer":"每次灌食前确认胃管位置并评估胃残余；灌注中出现呛咳、呼吸困难应立即停止。","reason":"具体考法：预防误吸比完成喂养量更优先。","source":"教材第270—273页"}],"numbers":[{"id":"ch11-number-1","title":"三大产能营养素","answer":"糖类4 kcal/g；脂肪9 kcal/g；蛋白质4 kcal/g","condition":"用于能量换算与配餐计算","source":"教材第258页"},{"id":"ch11-number-2","title":"成人每日能量供给","answer":"男性9.41～12.55 MJ/d；女性7.53～10.04 MJ/d","condition":"受年龄、性别、生理状态及劳动强度影响","source":"教材第258页"},{"id":"ch11-number-3","title":"BMI判断","answer":"18.5～24正常；24≤BMI＜28超重；BMI≥28肥胖；BMI＜18.5消瘦","condition":"BMI＝体重(kg)/身高²(m²)","source":"教材第263页"},{"id":"ch11-number-4","title":"标准体重","answer":"男性＝身高(cm)－105；女性＝身高(cm)－105－2.5","condition":"结合实测体重占标准体重百分数判断","source":"教材第263页"},{"id":"ch11-number-5","title":"普通饮食","answer":"2200～2600 kcal/d；蛋白质1～1.2 g/kg、70～90 g；脂肪0.8～1.0 g/kg、60～70 g；糖类275～350 g；水2500～3000 ml","condition":"消化功能正常、无饮食限制者，每日3餐","source":"教材第264页"},{"id":"ch11-number-6","title":"软质饮食","answer":"2200～2400 kcal/d；蛋白质60～80 g","condition":"消化吸收功能差、低热或术后恢复期，每日3～4餐","source":"教材第264页"},{"id":"ch11-number-7","title":"半流质饮食","answer":"1500～2000 kcal/d；蛋白质50～60 g；脂肪40～50 g；糖类250 g","condition":"口腔或消化道疾病、中等发热、体弱或术后，每日5～6餐","source":"教材第264页"},{"id":"ch11-number-8","title":"流质饮食","answer":"约800 kcal/d；蛋白质40～50 g；每次200～300 ml","condition":"每日6～7餐、每2～3小时一次，只宜短期使用","source":"教材第264页"},{"id":"ch11-number-9","title":"高热量饮食","answer":"约3000 kcal/d","condition":"基本饮食基础上加餐2次","source":"教材第264页"},{"id":"ch11-number-10","title":"高蛋白饮食","answer":"1.5～2.0 g/(kg·d)，总量≤120 g/d；总热量2500～3000 kcal/d","condition":"高代谢、贫血、大手术后等患者","source":"教材第264页"},{"id":"ch11-number-11","title":"限制蛋白质","answer":"成人≤0.8 g/(kg·d)","condition":"急慢性肾功能不全等患者；优先优质动物蛋白","source":"教材第265页"},{"id":"ch11-number-12","title":"限制脂肪与胆固醇","answer":"低脂＜50 g/d；肝胆胰疾病＜40 g/d；胆固醇＜300 mg/d","condition":"按疾病类型限制动物脂肪和高胆固醇食物","source":"教材第265页"},{"id":"ch11-number-13","title":"低盐与低钠","answer":"低盐食盐＜2 g/d；无盐饮食钠＜0.7 g/d；低钠饮食钠＜0.5 g/d","condition":"水肿、高血压及心肾疾病按医嘱选择","source":"教材第265页"},{"id":"ch11-number-14","title":"葡萄糖耐量试验饮食","answer":"试验前糖类＞300 g/d共3 d；禁食10～12 h；葡萄糖75 g溶于300 ml水","condition":"服糖后0.5、1、2、3 h采血","source":"教材第266页"},{"id":"ch11-number-15","title":"鼻饲管插入","answer":"成人约45～55 cm；到咽喉部约10～15 cm","condition":"按鼻尖—耳垂—剑突长度标记；清醒者到咽部后配合吞咽","source":"教材第270—272页"},{"id":"ch11-number-16","title":"分次鼻饲","answer":"38～40℃；每日4～6次；每次250～400 ml；速度≤30 ml/min","condition":"每次前确认管位、检查通畅，结束后冲管","source":"教材第271—272页"},{"id":"ch11-number-17","title":"鼻饲后体位","answer":"维持原卧位20～30 min","condition":"预防呕吐和误吸","source":"教材第271页"},{"id":"ch11-number-18","title":"鼻饲管更换与口腔护理","answer":"长期鼻饲每日口腔护理2次；普通胃管每周、硅胶胃管每月更换","condition":"晚间拔管，次晨从另一侧鼻孔插入","source":"教材第272页"},{"id":"ch11-number-19","title":"肠内营养输注","answer":"冲管每2～4 h；间歇输注3 h后休息2 h；连续输注12～24 h","condition":"冲洗液约37℃，防堵管并给患者休息","source":"教材第271、274页"},{"id":"ch11-number-20","title":"肠外营养输注速度","answer":"第1日60 ml/h，第2日80 ml/h，第3日100 ml/h","condition":"由低浓度、慢速度开始，逐渐增加","source":"教材第275页"},{"id":"ch11-number-21","title":"平衡膳食宝塔","answer":"盐＜5 g；油25～30 g；奶300～500 g；大豆坚果25～35 g；动物性食物120～200 g","condition":"另包括蔬菜300～500 g、水果200～350 g、谷类200～300 g、全谷杂豆50～150 g、薯类50～100 g、水1500～1700 ml、活动6000步/d","source":"教材第260页"},{"id":"ch11-number-22","title":"哺乳期额外需要","answer":"每日增加500 kcal，蛋白质需要量增至65 g/d","condition":"同时注意维生素B族和维生素C摄入","source":"教材第261页"},{"id":"ch11-number-23","title":"实测体重占标准体重","answer":"100%±10%正常；增加10%～20%超重，＞20%肥胖；减少10%～20%消瘦，＜－20%明显消瘦","condition":"与BMI及临床评估共同使用","source":"教材第263页"},{"id":"ch11-number-24","title":"三头肌皮褶厚度","answer":"男性12.5 mm；女性16.5 mm","condition":"低于正常值35%～40%为重度消耗，25%～34%中度，≤24%轻度","source":"教材第263页"},{"id":"ch11-number-25","title":"上臂围","answer":"男性平均27.5 cm；＞标准值90%正常，80%～90%轻度、60%～80%中度、＜60%重度营养不良","condition":"反映肌蛋白贮存和消耗程度","source":"教材第263页"},{"id":"ch11-number-26","title":"肌酐试验饮食","answer":"试验期3 d；全日主食≤300 g；蛋白质＜0.8 g/kg","condition":"禁食肉、禽、鱼及茶咖啡，第3日测内生肌酐清除率","source":"教材第265页"},{"id":"ch11-number-27","title":"尿浓缩功能试验饮食","answer":"试验1 d；全天水分500～600 ml；蛋白质1 g/(kg·d)","condition":"避免过甜、过咸及含水量高的食物","source":"教材第265页"},{"id":"ch11-number-28","title":"胆囊B超试验饮食","answer":"检查前3 d避产气食物；前1 d晚无脂肪、低蛋白、高糖；脂肪餐含脂肪约25～50 g","condition":"首次B超后进脂肪餐，30～45 min后复查","source":"教材第266页"},{"id":"ch11-number-29","title":"蛋白质推荐摄入量","answer":"男性65 g/d；女性55 g/d","condition":"18～49岁成年人参考摄入量","source":"教材第276页"},{"id":"ch11-number-30","title":"脂肪与糖类供能比","answer":"脂肪占总能量20%～30%；糖类占50%～65%","condition":"18～49岁成年人参考摄入量","source":"教材第276页"},{"id":"ch11-number-31","title":"常量与微量元素","answer":"钙800 mg；磷720 mg；镁330 mg；铁男12 mg、女20 mg；锌男12.5 mg、女7.5 mg；碘120 μg","condition":"18～49岁成年人每日推荐摄入量","source":"教材第276页"},{"id":"ch11-number-32","title":"脂溶性维生素","answer":"维生素A男800 μgRAE、女700 μgRAE；维生素D 10 μg；维生素E 14 mg α-TE；维生素K 80 μg","condition":"18～49岁成年人每日推荐摄入量","source":"教材第276—277页"},{"id":"ch11-number-33","title":"水溶性维生素","answer":"维生素B₁男1.4 mg、女1.2 mg；B₂男1.4 mg、女1.2 mg；B₆ 1.4 mg；B₁₂ 2.4 μg；叶酸400 μgDFE；维生素C 100 mg","condition":"18～49岁成年人每日推荐摄入量","source":"教材第277页"},{"id":"ch11-number-34","title":"水推荐摄入量","answer":"1500～1700 ml/d","condition":"包括饮用水、食物中水及体内代谢水","source":"教材第277页"},{"id":"ch11-number-35","title":"营养液保存与管路更换","answer":"配制液4℃以下保存且24 h内用完；输注管及袋每12～24 h更换；肠内营养容器每24 h清洗消毒","condition":"减少污染与感染风险","source":"教材第274—275页"},{"id":"ch11-number-36","title":"鼻饲冲管","answer":"每次喂食前后用少量温开水冲管","condition":"避免堵管并保证营养液或药物完整给入","source":"教材第271—273页"}],"compare":[{"title":"流质/半流质","items":["A：液体状、短期使用","B：半液体、营养更完整","决定性区别：看质地与适用时间"]},{"title":"鼻饲前确认/喂后冲管","items":["A：防止误入气道","B：保持通畅与完整给入","决定性区别：目的不同"]},{"title":"呛咳/正常吞咽","items":["A：提示误吸风险","B：无呼吸变化且吞咽协调","决定性区别：出现呛咳立即停止评估"]}],"questions":[{"id":"ch11-exam-1","title":"患者，女，40岁，因脑出血入院，意识不清，现遵医嘱留置胃管鼻饲饮食。下列预防误吸的护理措施正确的是（）","topic":"鼻饲","options":["A. 抽吸胃残余量大于120ml时应停止鼻饲","B. 鼻饲过程中患者一旦出现呛咳，应立即停止鼻饲，鼓励患者咳嗽，必要时经气管镜清除吸入物","C. 鼻饲时患者平卧","D. 配制完的营养液应在12小时内用完","E. 每2小时抽吸一次胃内残余量"],"answer":"正确答案：B．鼻饲过程中患者一旦出现呛咳，应立即停止鼻饲，鼓励患者咳嗽，必要时经气管镜清除吸入物","correct":["B"],"source":"教材第269—275页","paper":"暨南大学2023｜单项选择题"},{"id":"ch11-exam-2","title":"下列关于要素饮食的阐述，错误的是","topic":"鼻饲","options":["A. 配置好的溶液存放于4℃以下冰箱内，48小时内用完","B. 鼻饲温度41～42℃左右","C. 输注前后用温开水冲净管腔","D. 滴注时浓度、用量和速度从低、少、慢开始","E. 停用时逐渐减量，以免发生低血糖"],"answer":"正确答案：A．配置好的溶液存放于4℃以下冰箱内，48小时内用完","correct":["A"],"source":"教材第269—275页","paper":"杭州师范大学2020｜单项选择题"},{"id":"ch11-exam-3","title":"在鼻饲插管过程中病人出现呛咳、发绀，应采取的措施是","topic":"鼻饲","options":["A. 嘱病人深呼吸","B. 嘱病人做吞咽动作","C. 托起病人的头部插管","D. 用注射器抽吸胃液","E. 拔出胃管休息片刻后再插管"],"answer":"正确答案：E．拔出胃管休息片刻后再插管","correct":["E"],"source":"教材第269—275页","paper":"山西医科大学2012｜单项选择题"},{"id":"ch11-exam-4","title":"下列关于鼻饲法的描述，错误的是","topic":"鼻饲","options":["A. 插入胃管至10～15cm(咽喉部)时，清醒患者，嘱其做吞咽动作","B. 长期鼻饲者应每日进行口腔护理1次，硅胶胃管应每周更换1次","C. 鼻饲液温度应保持在38～40℃","D. 食道静脉曲张的患者禁忌使用鼻饲法","E. 每次鼻饲量不超过200ml，间隔时间不少于2h"],"answer":"正确答案：B．长期鼻饲者应每日进行口腔护理1次，硅胶胃管应每周更换1次","correct":["B"],"source":"教材第269—275页","paper":"青岛大学2013｜单项选择题"},{"id":"ch11-exam-5","title":"男性患者，52岁，自诉二个月前开始，解粘液血便，大便软不成形，每天3～5次，并有里急后重感，自认为是痔疮，用痔栓塞肛治疗无效，故来医院要治疗。经肠镜活检，确诊为直肠癌，决定行直肠癌根治术。术前进行肠道准备，下列措施正确的有","topic":"流质饮食","options":["A. 术前两日进流质饮食","B. 口服甲硝唑或新霉素等肠道抗生素","C. 手术前1日晚清洁灌肠","D. 术前2天口服缓泻剂","E. 术前8小时禁食，4小时禁水"],"answer":"正确答案：A．术前两日进流质饮食；B．口服甲硝唑或新霉素等肠道抗生素；C．手术前1日晚清洁灌肠；D．术前2天口服缓泻剂；E．术前8小时禁食，4小时禁水","correct":["A","B","C","D","E"],"source":"教材第264页","paper":"四川大学2012｜多项选择题"},{"id":"ch11-exam-6","title":"患者张女士，因肠梗阻入院，治疗6天后肠蠕动恢复，需要进流质饮食。下列不符合流质饮食原则的是","topic":"流质饮食","options":["A. 无刺激性","B. 每日3-4餐","C. 易吞咽、易消化","D. 只能短期使用","E. 可辅以场外营养以补充热量和营养"],"answer":"正确答案：B．每日3-4餐","correct":["B"],"source":"教材第264页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch11-exam-7","title":"在鼻饲插管过程中，如果发现病人呛咳、呼吸困难等情况，此时应采取的措施是","topic":"鼻饲","options":["A. 嘱病人深呼吸","B. 托起病人头部再插","C. 停止操作，取消鼻饲","D. 嘱病人作吞咽动作","E. 拔出管子，休息片刻后再重新插管"],"answer":"正确答案：E．拔出管子，休息片刻后再重新插管","correct":["E"],"source":"教材第269—275页","paper":"四川大学2009｜单项选择题"},{"id":"ch11-exam-8","title":"护士为昏迷患者插胃管至15cm处要将患者头部托起。护士应明白这样做的目的是","topic":"鼻饲管插入","options":["A. 加大咽喉部通道的弧度","B. 以免损伤食管黏膜","C. 减轻患者痛苦","D. 避免出现恶心","E. 使喉部肌肉放松便于插入"],"answer":"正确答案：A．加大咽喉部通道的弧度","correct":["A"],"source":"教材第270—272页","paper":"扬州大学2023｜单项选择题"},{"id":"ch11-exam-9","title":"全麻术后预防病人发生误吸的有效措施是：","topic":"鼻饲","options":["A. 应用止吐药","B. 应用阿托品","C. 留置鼻饲管","D. 禁食禁饮","E. 麻醉清醒前去枕平卧二、多选题（30道题，每题2分，共60分）"],"answer":"正确答案：E．麻醉清醒前去枕平卧二、多选题（30道题，每题2分，共60分）","correct":["E"],"source":"教材第269—275页","paper":"四川大学2010｜单项选择题"},{"id":"ch11-exam-10","title":"王某，男，28岁。头痛流涕。咽痛已1周，昨天起出现四肢麻木无力、且自远端向近端扩展，伴饮水呛咳及呼吸困难收治入院。以下护理措施最重要的是","topic":"鼻饲","options":["A. 亲切关怀、安慰患者，稳定情绪","B. 维持呼吸功能，保持呼吸道通畅","C. 鼻饲流质，补充营养","D. 保护肢体，防止冻伤或烫伤","E. 按摩四肢，增加血循环"],"answer":"正确答案：B．维持呼吸功能，保持呼吸道通畅","correct":["B"],"source":"教材第269—275页","paper":"扬州大学2023｜单项选择题"}]},{"id":"ch12","number":12,"title":"排泄","page":"ch12-elimination.html","lab":"ch12-learning-lab.html","core":[{"id":"ch12-core-1","title":"排尿评估","answer":"结合次数、量、颜色、气味、症状和出入量识别尿潴留、少尿等异常。","reason":"具体考法：不能只看单次尿量，要联系时间与病情。","source":"教材第279—284页"},{"id":"ch12-core-2","title":"导尿","answer":"严格无菌、正确辨认尿道、轻柔插入、保护隐私并预防逆行感染。","reason":"具体考法：误入阴道必须更换无菌导尿管再插。","source":"教材第284—291页"},{"id":"ch12-core-3","title":"留置导尿","answer":"保持密闭通畅、尿袋低于膀胱、避免受压扭曲并做好会阴护理。","reason":"具体考法：不常规随意分离接口或夹闭。","source":"教材第286—291页"},{"id":"ch12-core-4","title":"排便评估","answer":"关注次数、性状、颜色、气味、疼痛及排便习惯，先处理可逆原因。","reason":"具体考法：便秘护理应含饮食、活动、排便训练。","source":"教材第292—297页"},{"id":"ch12-core-5","title":"灌肠","answer":"依据目的选择溶液、量、温度、体位和插入深度，并观察腹痛、出血和反应。","reason":"具体考法：肝昏迷、充血性心衰等特殊患者要辨溶液禁忌。","source":"教材第297—305页"},{"id":"ch12-core-6","title":"尿失禁辨析","answer":"真性、充溢性、压力性、急迫性和功能性尿失禁的病因与表现不同。","reason":"具体考法：看膀胱是否过度充盈、是否有强烈尿意及诱发动作。","source":"教材第282—285页"},{"id":"ch12-core-7","title":"导尿感染预防","answer":"无菌置管、保持密闭、尿袋低于膀胱、避免反流和不必要断开，尽早拔管。","reason":"具体考法：常规冲洗和频繁更换并不能替代密闭与尽早拔管。","source":"教材第287—291页"},{"id":"ch12-core-8","title":"灌肠禁忌","answer":"急腹症、消化道出血、妊娠、严重心血管病等需慎用或禁用大量不保留灌肠。","reason":"具体考法：先看禁忌再计算温度、深度和高度。","source":"教材第299—301页"}],"numbers":[{"id":"ch12-number-1","title":"成人排尿","answer":"日间4～6次、夜间0～2次；每次200～400 ml","condition":"24 h约1000～2000 ml，平均1500 ml","source":"教材第280页"},{"id":"ch12-number-2","title":"多尿","answer":"＞2500 ml/24 h","condition":"结合饮水、用药和疾病判断","source":"教材第281页"},{"id":"ch12-number-3","title":"少尿","answer":"＜400 ml/24 h或＜17 ml/h","condition":"提示灌注或肾功能问题","source":"教材第281页"},{"id":"ch12-number-4","title":"无尿","answer":"＜100 ml/24 h或12 h无尿","condition":"需立即评估梗阻和肾功能","source":"教材第281页"},{"id":"ch12-number-5","title":"导尿见尿后","answer":"继续插入5～7 cm","condition":"留置导尿后再充盈气囊","source":"教材第289页"},{"id":"ch12-number-6","title":"导尿气囊","answer":"注入10～15 ml液体","condition":"按导管标识执行","source":"教材第289页"},{"id":"ch12-number-7","title":"留置导尿护理","answer":"会阴/尿道口1～2次/d；集尿袋每周1～2次更换","condition":"保持密闭和低位引流","source":"教材第290页"},{"id":"ch12-number-8","title":"留置导尿更换","answer":"导尿管约1～4周","condition":"结合材质、尿液pH和堵塞风险","source":"教材第290页"},{"id":"ch12-number-9","title":"预防结石饮水","answer":"无禁忌时＞2000 ml/d","condition":"形成冲洗作用","source":"教材第290页"},{"id":"ch12-number-10","title":"膀胱冲洗","answer":"液温38～40℃；每次200～300 ml；60～80滴/min；液面高约60 cm","condition":"观察引流颜色与通畅","source":"教材第291页"},{"id":"ch12-number-11","title":"成人排便","answer":"1～3次/d至1次/2～3 d均可","condition":"以个人规律和性状为准","source":"教材第293页"},{"id":"ch12-number-12","title":"便秘","answer":"每周排便＜3次","condition":"伴排便困难或粪便干硬","source":"教材第293页"},{"id":"ch12-number-13","title":"膳食纤维和饮水","answer":"纤维25～35 g/d；饮水1500～2000 ml/d","condition":"无禁忌时预防便秘","source":"教材第297页"},{"id":"ch12-number-14","title":"大量不保留灌肠","answer":"成人500～1000 ml，儿童200～500 ml；液温39～41℃","condition":"高热降温用28～32℃，中暑约4℃","source":"教材第300页"},{"id":"ch12-number-15","title":"灌肠筒高度","answer":"液面距肛门40～60 cm","condition":"控制压力和速度","source":"教材第300页"},{"id":"ch12-number-16","title":"肛管插入","answer":"成人7～10 cm","condition":"大量不保留灌肠","source":"教材第300页"},{"id":"ch12-number-17","title":"导尿管更换与尿pH","answer":"pH＞6.8约2周；pH＜6.7约4周；混浊约3周","condition":"按堵塞风险个体化","source":"教材第290页"},{"id":"ch12-number-18","title":"肠道准备","answer":"总量3000～4000 ml；首次600～1000 ml，其后每10～15 min 250 ml，最多4 L","condition":"观察排出液与耐受","source":"教材第298页"},{"id":"ch12-number-19","title":"伤寒灌肠","answer":"液面≤30 cm、总量≤500 ml","condition":"防肠穿孔","source":"教材第300页"},{"id":"ch12-number-20","title":"保留灌肠深度","answer":"成人15～20 cm；幼儿5～7.5 cm；婴儿2.5～4 cm","condition":"慢性菌痢常取左侧卧位","source":"教材第302页"},{"id":"ch12-number-21","title":"肛管排气","answer":"插入15～18 cm，每次≤20 min","condition":"间隔2～3 h后再用","source":"教材第305页"}],"compare":[{"title":"尿潴留/尿失禁","items":["A：膀胱充盈但不能排出","B：尿液不自主流出","决定性区别：看膀胱是否充盈"]},{"title":"大量/小量不保留灌肠","items":["A：清洁肠道、量大","B：药液保留、量小","决定性区别：目的和液量不同"]},{"title":"保留灌肠左侧卧位/其他体位","items":["A：使药液沿结肠保留","B：按病变部位调整","决定性区别：题干目的决定体位"]}],"questions":[{"id":"ch12-exam-1","title":"关于导尿操作的叙述，正确的是","topic":"导尿操作","options":["A. 给男病人插导尿管时提起阴茎与腹壁成60°角，可使耻骨前弯消失","B. 女病人导尿时，导尿管插入尿道4～6 cm，见尿液后再插入3～4 cm","C. 对膀胱高度膨胀而又极度虚弱的患者，第一次放尿不应超过2000 ml","D. 女性导尿误入阴道时，应立即拔出原导尿管后重新插入","E. 留置导尿期间，用酒精棉球消毒尿道口及外阴1～2次/天"],"answer":"正确答案：A．给男病人插导尿管时提起阴茎与腹壁成60°角，可使耻骨前弯消失","correct":["A"],"source":"教材第284—291页","paper":"湖州师范学院2018｜单项选择题"},{"id":"ch12-exam-2","title":"伤寒患者灌肠时，灌肠筒内液面不得高于肛门多少厘米，液体量不得超过多少毫升","topic":"特殊患者灌肠","options":["A. 20 cm，300 ml","B. 30 cm，500 ml","C. 40 cm，500 ml","D. 35 cm，600 ml","E. 60 cm，300 ml"],"answer":"正确答案：B．液面不得高于肛门30 cm，液体量不得超过500 ml","correct":["B"],"source":"教材第299—301页","paper":"哈尔滨医科大学2013｜单项选择题"},{"id":"ch12-exam-3","title":"长期留置导尿的病人，出现尿液混浊、沉淀或结晶时应:","topic":"留置导尿护理","options":["A. 经常清洁尿道口","B. 膀胱内用药","C. 热敷下腹部","D. 多饮水，并进行膀胱冲洗","E. 经常更换卧位"],"answer":"正确答案：D．多饮水，并进行膀胱冲洗","correct":["D"],"source":"教材第289—291页","paper":"浙江大学2011｜单项选择题"},{"id":"ch12-exam-4","title":"患者腰麻术后4小时，烦躁不安，生命体征无异常。查体：下腹部膨隆，叩诊浊音。首先应考虑","topic":"尿潴留识别","options":["A. 肠梗阻","B. 尿潴留","C. 急性胃扩张","D. 腹腔内出血","E. 急性腹膜炎"],"answer":"正确答案：B．尿潴留","correct":["B"],"source":"教材第281—284页","paper":"杭州师范大学2018｜单项选择题"},{"id":"ch12-exam-5","title":"患者王某，女50岁，脾切除术后6小时未排尿，患者主述下腹胀满不适、胀痛难忍。检体：耻骨上膨隆，扪及囊样包块。对该患者采取的措施中不正确的是","topic":"尿潴留处理","options":["A. 轻轻按摩下腹部","B. 用温水冲洗会阴","C. 让患者听流水声","D. 口服利尿药","E. 导尿术"],"answer":"正确答案：D．口服利尿药","correct":["D"],"source":"教材第282—286页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch12-exam-6","title":"对便秘患者进行健康指导时，哪种做法不妥","topic":"便秘健康教育","options":["A. 生活规律，定时排便","B. 病情许可时，协助下床活动","C. 多食富有粗纤维的食物","D. 摄取适量油脂食物","E. 每晚睡前使用开塞露"],"answer":"正确答案：E．每晚睡前使用开塞露","correct":["E"],"source":"教材第293—297页","paper":"四川大学2009｜单项选择题"},{"id":"ch12-exam-7","title":"患者万某，慢性菌痢，用保留灌肠治疗，操作过程正确的是","topic":"保留灌肠","options":["A. 患者取右侧卧位","B. 灌入量500 ml","C. 肛管插入7 cm","D. 灌入后保留1小时以上","E. 液面距肛门不超过60 cm"],"answer":"正确答案：D．灌入后保留1小时以上","correct":["D"],"source":"教材第301—303页","paper":"杭州师范大学2013｜单项选择题"},{"id":"ch12-exam-8","title":"对肝昏迷患者实施灌肠治疗时，应禁忌使用","topic":"灌肠禁忌","options":["A. 生理盐水","B. 肥皂水","C. 新霉素液","D. 弱酸性溶液","E. 石蜡油"],"answer":"正确答案：B．肥皂水","correct":["B"],"source":"教材第297—303页","paper":"四川大学2010｜单项选择题"},{"id":"ch12-exam-9","title":"患者男，76岁。有良性前列腺增生病史15年。今日饮酒后突发急性尿潴留，腹胀难忍，诱导排尿无效。此时应采取的措施是","topic":"急性尿潴留","options":["A. 导尿后拔出导尿管","B. 导尿并留置导尿","C. 耻骨上膀胱穿刺","D. 按压膀胱","E. 耻骨上膀胱造瘘"],"answer":"正确答案：B．导尿并留置导尿","correct":["B"],"source":"教材第284—291页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch12-exam-10","title":"对排尿异常的观察，描述错误的是（）","topic":"排尿异常","options":["A. 多尿是指24小时尿量超过2500 ml","B. 少尿是指24小时尿量少于100 ml","C. 膀胱刺激征的主要表现为尿频、尿急和尿痛","D. 尿潴留是尿液存留在膀胱而不能自主排出","E. 尿失禁是排尿不受意识控制，尿液不自主流出"],"answer":"正确答案：B．少尿是指24小时尿量少于100 ml","correct":["B"],"source":"教材第280—284页","paper":"河南大学2008｜单项选择题"}]},{"id":"ch13","number":13,"title":"给药","page":"ch13-medication.html","lab":"ch13-learning-lab.html","core":[{"id":"ch13-core-1","title":"安全给药","answer":"执行查对制度，确认患者、药物、剂量、途径、时间和记录，并解释用药。","reason":"具体考法：任何异常医嘱都应先核实，不能盲目执行。","source":"教材第307—312页"},{"id":"ch13-core-2","title":"口服给药","answer":"依据药物剂型、作用和患者吞咽能力安排，特殊剂型不得随意掰碎。","reason":"具体考法：健胃药、助消化药、催眠药等给药时间常考。","source":"教材第313—315页"},{"id":"ch13-core-3","title":"注射给药","answer":"选择合适部位和针具，严格无菌，避免神经血管并观察局部反应。","reason":"具体考法：皮内、皮下、肌内和静脉注射的角度、深度与用途要配对。","source":"教材第315—331页"},{"id":"ch13-core-4","title":"雾化吸入","answer":"依据治疗目的选药，正确连接装置并指导深慢吸气、屏气和呼气。","reason":"具体考法：氧气雾化要同时考流量和禁火防油。","source":"教材第331—338页"},{"id":"ch13-core-5","title":"药物过敏试验","answer":"用药前核对过敏史与试验条件，按时判断；阳性或过敏反应立即处理。","reason":"具体考法：青霉素过敏性休克首选肾上腺素。","source":"教材第338—345页"},{"id":"ch13-core-6","title":"三查八对","answer":"给药前、中、后查对；核对床号、姓名、药名、浓度、剂量、方法、时间和药品有效期等。","reason":"具体考法：开放式询问身份，不能只问‘你是不是某某’。","source":"教材第310—313页"},{"id":"ch13-core-7","title":"给药时间缩写","answer":"ac、pc、hs、prn、sos等必须和给药条件、频次一起识别。","reason":"具体考法：不要只凭字母形状猜时间。","source":"教材第314—315页"},{"id":"ch13-core-8","title":"过敏性休克抢救","answer":"立即停药、平卧保暖、就地抢救，首选肾上腺素，同时维持气道和循环。","reason":"具体考法：顺序题先停致敏药并给肾上腺素，不能先等待医生到场。","source":"教材第342—343页"}],"numbers":[{"id":"ch13-number-1","title":"皮内注射","answer":"5°进针，常注0.1 ml","condition":"皮试和局部试验","source":"教材第321页"},{"id":"ch13-number-2","title":"卡介苗皮内注射","answer":"10°～15°","condition":"上臂三角肌下缘","source":"教材第321页"},{"id":"ch13-number-3","title":"皮下注射","answer":"30°～40°，刺入针梗1/2～2/3","condition":"短针可90°进针","source":"教材第323页"},{"id":"ch13-number-4","title":"肌内注射","answer":"90°，刺入针梗1/2～2/3","condition":"避开血管神经","source":"教材第326页"},{"id":"ch13-number-5","title":"静脉注射","answer":"15°～30°","condition":"见回血后固定","source":"教材第330页"},{"id":"ch13-number-6","title":"皮试观察","answer":"20 min","condition":"期间不得离开","source":"教材第340页"},{"id":"ch13-number-7","title":"青霉素皮试液","answer":"0.1 ml含50 U","condition":"现配现用","source":"教材第340页"},{"id":"ch13-number-8","title":"首次用药观察","answer":"注射后观察30 min","condition":"重点警惕过敏反应","source":"教材第340页"},{"id":"ch13-number-9","title":"氧气雾化流量","answer":"6～8 L/min","condition":"利用高速氧流形成雾滴","source":"教材第334页"},{"id":"ch13-number-10","title":"超声雾化水槽","answer":"水温≤50℃","condition":"防止机器损坏和烫伤","source":"教材第333页"},{"id":"ch13-number-11","title":"过敏性休克肾上腺素","answer":"0.1% 0.5～1 ml","condition":"立即皮下或肌内注射并按病情重复","source":"教材第343页"},{"id":"ch13-number-12","title":"结核菌素试验","answer":"48～72 h观察","condition":"测量硬结横径","source":"教材第344页"},{"id":"ch13-number-13","title":"胰岛素笔针4～5 mm","answer":"通常90°进针","condition":"多数成人无需捏皮","source":"教材第328页"},{"id":"ch13-number-14","title":"较长胰岛素针","answer":"≥8 mm时常捏皮45°进针","condition":"减少肌内注射风险","source":"教材第328页"}],"compare":[{"title":"皮内/皮下","items":["A：试验和局部麻醉，角度小","B：胰岛素等，进入皮下组织","决定性区别：用途和角度一起记"]},{"title":"过敏反应/晕针","items":["A：常伴皮疹、呼吸循环异常","B：面色苍白、脉慢或短暂意识变化","决定性区别：生命体征和皮肤呼吸表现不同"]},{"title":"硬结/红晕","items":["A：皮试判断测硬结","B：皮肤充血范围","决定性区别：结核菌素尤其易混"]}],"questions":[{"id":"ch13-exam-1","title":"以下不属于给药原则“七对”的是（）","topic":"安全给药","options":["A. 药名","B. 剂量","C. 途径","D. 护士"],"answer":"正确答案：D．护士","correct":["D"],"source":"教材第307—312页","paper":"吉林大学2018｜单项选择题"},{"id":"ch13-exam-2","title":"患者，男，50岁，经常发生肾绞痛、血尿，疑为肾结石，需作静脉肾盂造影。造影前准备下列哪项不正确","topic":"药物过敏试验","options":["A. 常规肠道准备","B. 当天禁止早餐","C. 鼓励饮水","D. 检查前排尽小便","E. 需作碘过敏试验"],"answer":"正确答案：C．鼓励饮水","correct":["C"],"source":"教材第338—345页","paper":"青岛大学2011｜单项选择题"},{"id":"ch13-exam-3","title":"肌内注射部位应选择","topic":"肌内注射","options":["A. 肌肉丰厚处","B. 远离神经、大血管处","C. 皮肤无炎症、硬结处","D. 皮下脂肪丰厚处","E. 皮肤无受损处"],"answer":"正确答案：A．肌肉丰厚处；B．远离神经、大血管处；C．皮肤无炎症、硬结处；E．皮肤无受损处","correct":["A","B","C","E"],"source":"教材第326页","paper":"复旦大学2015｜多项选择题"},{"id":"ch13-exam-4","title":"下列有关给药原则的描述，正确的是（）","topic":"安全给药","options":["A. 根据医嘱给药，一般不执行口头医嘱","B. 准确掌握给药时间、方法","C. 操作中做到三查七对一注意","D. 护士根据病情自行调整用药方案","E. 给药后观察疗效和不良反应并记录"],"answer":"正确答案：A．根据医嘱给药，一般不执行口头医嘱；B．准确掌握给药时间、方法；C．操作中做到三查七对一注意；E．给药后观察疗效和不良反应并记录","correct":["A","B","C","E"],"source":"教材第307—312页","paper":"浙江中医药大学2018｜多项选择题"},{"id":"ch13-exam-5","title":"下列有关给药原则的描述错误的是（）","topic":"安全给药","options":["A. 根据医嘱给药，护士一般不执行口头医嘱","B. 给药过程中医嘱或药物有任何疑问，应立即提出，询问明确后方可给药","C. 操作中要做到三查七对一注意","D. 对易发生过敏的药物应停止使用","E. 给药后要注意观察其药物的疗效和不良反应"],"answer":"正确答案：D．对易发生过敏的药物应停止使用","correct":["D"],"source":"教材第307—312页","paper":"河南大学2008｜单项选择题"},{"id":"ch13-exam-6","title":"进行体位引流时，正确的有（）","topic":"雾化吸入","options":["A. 体位选择是使病变部位处于高处，引流支气管开口向下","B. 体位引流适合于任何病人","C. 引流通常在餐前或睡前进行","D. 引流前应给予超声雾化吸入","E. 引流时应辅以胸部扣击"],"answer":"正确答案：A．体位选择是使病变部位处于高处，引流支气管开口向下；C．引流通常在餐前或睡前进行；D．引流前应给予超声雾化吸入；E．引流时应辅以胸部扣击","correct":["A","C","D","E"],"source":"教材第331—338页","paper":"陕西中医药大学2008-2009｜多项选择题"},{"id":"ch13-exam-7","title":"有关肺癌行手术治疗的患者，术前正确的护理措施是","topic":"雾化吸入","options":["A. 指导并劝告病人戒烟","B. 练习腹式呼吸","C. 禁用机械通气治疗","D. 注意口腔卫生，治疗牙周疾病，以免手术后并发肺部感染","E. 痰液粘稠时不宜予超声雾化"],"answer":"正确答案：A．指导并劝告病人戒烟；B．练习腹式呼吸；D．注意口腔卫生，治疗牙周疾病，以免手术后并发肺部感染","correct":["A","B","D"],"source":"教材第331—338页","paper":"山西医科大学2012｜多项选择题"},{"id":"ch13-exam-8","title":"为患者做药物过敏试验前，下列选项中最重要的是","topic":"药物过敏试验","options":["A. 环境清洁","B. 准备好皮肤消毒液","C. 询问有无药物过敏史","D. 选择合适的注射部位","E. 为患者安置舒适的体位"],"answer":"正确答案：C．询问有无药物过敏史","correct":["C"],"source":"教材第338—345页","paper":"杭州师范大学2016｜单项选择题"},{"id":"ch13-exam-9","title":"患者侧卧进行肌内注射时，正确的体位摆放是（）","topic":"肌内注射","options":["A. 下腿伸直，上腿稍弯曲","B. 上腿伸直，下腿稍弯曲","C. 双膝向腹部弯曲","D. 两腿弯曲"],"answer":"正确答案：B．上腿伸直，下腿稍弯曲","correct":["B"],"source":"教材第326页","paper":"浙江中医药大学2021｜单项选择题"},{"id":"ch13-exam-10","title":"不宜做青霉素过敏试验的是:","topic":"药物过敏试验","options":["A. 首次用药者","B. 停药3天","C. 已知患者有青霉素过敏史","D. 使用中途更换批号","E. 以往皮试阴性者"],"answer":"正确答案：C．已知患者有青霉素过敏史","correct":["C"],"source":"教材第338—345页","paper":"陕西中医药大学2008-2009｜单项选择题"}]},{"id":"ch14","number":14,"title":"静脉输液与输血","page":"ch14-infusion-transfusion.html","lab":"ch14-learning-lab.html","core":[{"id":"ch14-core-1","title":"静脉输液","answer":"依据脱水、电解质、营养和治疗目标选择液体，规范排气、穿刺和固定。","reason":"具体考法：题干常考滴速计算与巡视。","source":"教材第356—365页"},{"id":"ch14-core-2","title":"输液反应","answer":"发热、循环负荷过重、静脉炎和空气栓塞需从线索中快速辨认。","reason":"具体考法：先停或调输液并按类型采取体位、氧疗和报告。","source":"教材第365—371页"},{"id":"ch14-core-3","title":"输血前","answer":"核对血型、交叉配血、血袋与患者，评估病情并建立合适通路。","reason":"具体考法：输血前后及两袋血之间用0.9%氯化钠。","source":"教材第372—376页"},{"id":"ch14-core-4","title":"输血过程","answer":"开始慢速，严密观察，确认无反应后按病情调整；血制品不得随意加药。","reason":"具体考法：最初15分钟是反应观察重点。","source":"教材第376—381页"},{"id":"ch14-core-5","title":"输血反应","answer":"过敏、发热、溶血、循环负荷过重和细菌污染反应需按出现时间与表现判断。","reason":"具体考法：疑似溶血立即停止输血，保留余血并送检。","source":"教材第381—388页"},{"id":"ch14-core-6","title":"输液反应鉴别","answer":"发热反应以寒战高热为主；循环负荷过重见突发呼吸困难、粉红泡沫痰；静脉炎沿静脉红肿疼痛；空气栓塞可突发胸闷濒死感。","reason":"具体考法：先凭最有区分度的线索定位，再采取相应体位和处理。","source":"教材第367—372页"},{"id":"ch14-core-7","title":"血制品选择","answer":"全血、红细胞、血小板、血浆和冷沉淀适应证不同。","reason":"具体考法：贫血并非一律输全血，要看缺少哪种成分。","source":"教材第374—379页"},{"id":"ch14-core-8","title":"输血反应处置","answer":"怀疑反应立即停止输血，换生理盐水维持静脉通路，核对并报告，保留血袋送检。","reason":"具体考法：不能仅减慢滴速后继续观察。","source":"教材第380—384页"}],"numbers":[{"id":"ch14-number-1","title":"滴系数","answer":"10、15或20滴/ml","condition":"先核对输液器标识再计算","source":"教材第366页"},{"id":"ch14-number-2","title":"成人输液速度","answer":"40～60滴/min","condition":"按年龄、病情、药物调整","source":"教材第361页"},{"id":"ch14-number-3","title":"儿童输液速度","answer":"20～40滴/min","condition":"需更严格控制","source":"教材第361页"},{"id":"ch14-number-4","title":"补钾见尿","answer":"尿量＞40 ml/h或＞500 ml/d","condition":"排尿不足先不补钾","source":"教材第359页"},{"id":"ch14-number-5","title":"成人补钾总量","answer":"约60～80 mmol/d，氯化钾约4.5～6 g","condition":"按血钾和肾功能调整","source":"教材第359页"},{"id":"ch14-number-6","title":"输液器更换","answer":"至少每24 h","condition":"污染或疑似污染立即更换","source":"教材第362页"},{"id":"ch14-number-7","title":"急性肺水肿轮扎","answer":"每5～10 min轮换一个肢体","condition":"一次只扎三个肢体","source":"教材第369页"},{"id":"ch14-number-8","title":"急性肺水肿放血","answer":"约200～300 ml","condition":"特殊情况下遵医嘱","source":"教材第369页"},{"id":"ch14-number-9","title":"输血初始观察","answer":"开始15 min内慢速并床旁观察","condition":"无反应再按医嘱调速","source":"教材第377—378页"},{"id":"ch14-number-10","title":"血液取回与完成","answer":"取回后30 min内开始，单袋通常4 h内输完","condition":"不得随意加热或放置","source":"教材第377—378页"},{"id":"ch14-number-11","title":"血袋保留","answer":"输血后保存24 h","condition":"便于反应追查","source":"教材第378页"},{"id":"ch14-number-12","title":"直接输血抗凝","answer":"3.8%枸橼酸钠5 ml/50 ml血","condition":"按采血量准确配比","source":"教材第378页"},{"id":"ch14-number-13","title":"溶血反应出现量","answer":"输入约10～15 ml即可发生","condition":"一旦怀疑立即停止输血","source":"教材第383页"},{"id":"ch14-number-14","title":"交叉配血采血","answer":"常取血约2 ml","condition":"严格身份核对","source":"教材第376页"},{"id":"ch14-number-15","title":"输血前后冲管","answer":"用0.9%氯化钠","condition":"血液中不得加入其他药物","source":"教材第378页"}],"compare":[{"title":"发热反应/溶血反应","items":["A：寒战高热为主","B：腰背痛、血红蛋白尿和休克","决定性区别：出现时间与尿色是关键"]},{"title":"静脉炎/渗出","items":["A：沿静脉红肿疼痛","B：局部肿胀、滴速减慢","决定性区别：看是否沿静脉走向"]},{"title":"输液过快/空气栓塞","items":["A：呼吸困难、肺水肿","B：突发胸闷、濒死感、右心气泡音","决定性区别：诱因和体位处理不同"]}],"questions":[{"id":"ch14-exam-1","title":"患者，女性，70岁。因频繁呕吐、腹泻、全身无刀急诊入院，入院后查血清锦3.2mrnol/L，医嘱予10%的氮化饵iOrnl加入5%葡萄语氧化钧洛注500ml静，咏滴注QD。患者输液过程中患者突然出现呼吸困难，民闷明显，咳粉红色泡沫痰。患者出现的情况可能是（","topic":"输液反应鉴别","options":["A. 发热反应","B. 空气栓塞","C. 过敏反应","D. 循环负荷过重","E. 细菌污染反应"],"answer":"正确答案：D．循环负荷过重","correct":["D"],"source":"教材第367—372页","paper":"浙江中医药大学2020｜单项选择题"},{"id":"ch14-exam-2","title":"严宏，男，54岁，因肝硬化，食管静脉曲张破裂大呕血急诊入院。遵医嘱输血。在输血过程中，患者出现手足抽搐．血压下降．出血倾向。此患者可能出现的情况是","topic":"输血过程","options":["A. 溶血反应","B. 发热反应","C. 休克","D. 枸橼酸钠中毒反应","E. 过敏反应"],"answer":"正确答案：D．枸橼酸钠中毒反应","correct":["D"],"source":"教材第376—381页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch14-exam-3","title":"王先生，35岁，车祸手术，术中遵医嘱给予静脉输血，数分钟后发生输血反应其尿液颜色呈","topic":"输血反应","options":["A. 正常","B. 酱油色","C. 乳白色","D. 洗肉水样","E. 深黄色"],"answer":"正确答案：B．酱油色","correct":["B"],"source":"教材第381—388页","paper":"山西医科大学2012｜单项选择题"},{"id":"ch14-exam-4","title":"输血引起溶血反应的预防措施是","topic":"输血前","options":["A. 输血前认真核对","B. 作好血型鉴定","C. 严格执行血液保存规则","D. 作好交叉配血试验","E. 库血从血库取出，加温后使用"],"answer":"正确答案：A．输血前认真核对；B．作好血型鉴定；C．严格执行血液保存规则；D．作好交叉配血试验","correct":["A","B","C","D"],"source":"教材第372—376页","paper":"杭州师范大学2019｜多项选择题"},{"id":"ch14-exam-5","title":"某患者因车祸大量失血入院，需输血治疗。考虑到时间紧迫，在配血完成后，护士从血库取回血，将血袋放入热水中紧急提温5分钟，之后迅速给患者输入。当输入10min后，患者感到头部胀痛，并且出现恶心呕吐，腰背部剧痛。该患者最可能出现了（）","topic":"溶血反应出现量","options":["A. 过敏反应","B. 高钾血症","C. 低血钙","D. 溶血反应","E. 酸中毒"],"answer":"正确答案：D．溶血反应","correct":["D"],"source":"教材第383页","paper":"暨南大学2015｜单项选择题"},{"id":"ch14-exam-6","title":"静脉输液时，患者滴数极馒，注射处肿胀，无回血，正确处理方法是：","topic":"静脉输液","options":["A. 调整针头位置","B. 更换针头重新穿刺","C. 抬高输液瓶的位置","D. 用手挤压输液管","E. 适当改变肢体位置"],"answer":"正确答案：B．更换针头重新穿刺","correct":["B"],"source":"教材第356—365页","paper":"湖州师范学院2020｜单项选择题"},{"id":"ch14-exam-7","title":"患者张某，在加压输液过程中突然感到胸部异常不适，随后出现呼吸困难，严重发绀，下列可能出现的问题及首要处理正确的是","topic":"输液反应鉴别","options":["A. 肺水肿，停止输液","B. 心脏病发作，立即遵医嘱用强心剂","C. 过敏，皮下注射地塞米松","D. 空气栓塞，立即左侧卧位","E. 低血容量性休克，立即补充血容量l"],"answer":"正确答案：D．空气栓塞，立即左侧卧位","correct":["D"],"source":"教材第367—372页","paper":"中南大学2013｜单项选择题"},{"id":"ch14-exam-8","title":"全身麻醉清醒前，最重要的护理是","topic":"静脉输液","options":["A. 定时测生命体征","B. 保持呼吸道通畅","C. 持续静脉输液","D. 观察伤口渗血情况","E. 防止意外损伤"],"answer":"正确答案：B．保持呼吸道通畅","correct":["B"],"source":"教材第356—365页","paper":"杭州师范大学2013｜单项选择题"},{"id":"ch14-exam-9","title":"男性，56岁，肺癌化疗患者，右下肢肿胀，多普勒超声检查显示右下肢深静脉炎。突感胸闷、气急、胸痛。查体：心率100次/分，律齐，P2亢进，三尖瓣区闻及收缩期杂音。两肺未闻异常。有高血压、冠心病史。首先应怀疑的疾病是","topic":"输液反应鉴别","options":["A. 肺癌阻塞大气道","B. 肺癌合并肺部感染","C. 化疗副作用","D. 肺栓塞","E. 心力衰竭"],"answer":"正确答案：D．肺栓塞","correct":["D"],"source":"教材第367—372页","paper":"青岛大学2009｜单项选择题"},{"id":"ch14-exam-10","title":"女性，47岁，十二指肠溃疡急性穿孔。行毕Ⅱ式胃大部切除术后第1天，护士查房时见胃肠减压管内吸出咖啡色胃液约280ml。正确的处理是:","topic":"静脉输液","options":["A. 继续观察，不需特殊处理","B. 加快静脉输液速度","C. 应用止血药","D. 胃管内灌注冰盐水","E. 马上做好手术止血的准备"],"answer":"正确答案：A．继续观察，不需特殊处理","correct":["A"],"source":"教材第356—365页","paper":"汕头大学2022｜单项选择题"}]},{"id":"ch15","number":15,"title":"标本采集","page":"ch15-specimen-collection.html","lab":"ch15-learning-lab.html","core":[{"id":"ch15-core-1","title":"标本原则","answer":"正确、及时、足量、具有代表性，并在用药或饮食影响前后按要求采集。","reason":"具体考法：不能从输液同侧直接采血或擅自改变采集时间。","source":"教材第394—396页"},{"id":"ch15-core-2","title":"血液标本","answer":"不同检验选择相应试管和抗凝剂，严格核对并避免溶血。","reason":"具体考法：多管采血顺序和血培养无菌要求常考。","source":"教材第396—403页"},{"id":"ch15-core-3","title":"尿标本","answer":"常规、中段、定时、培养等目的不同，容器和留取方法随之改变。","reason":"具体考法：尿培养强调清洁外阴和无菌中段尿。","source":"教材第404—407页"},{"id":"ch15-core-4","title":"粪便标本","answer":"从异常部分取材，隐血试验需控制饮食和药物干扰。","reason":"具体考法：标本不能混入尿液、消毒剂或其他污染物。","source":"教材第407—409页"},{"id":"ch15-core-5","title":"痰与咽拭子","answer":"深呼吸咳出下呼吸道痰，咽拭子避免触及口腔非目标部位并及时送检。","reason":"具体考法：培养标本一般在抗菌药使用前留取。","source":"教材第409—413页"},{"id":"ch15-core-6","title":"采血管颜色与用途","answer":"白/红/深黄多用于血清；绿系肝素血浆；紫色EDTA全血；浅蓝枸橼酸钠1:9用于凝血；黑色1:4用于血沉；浅灰抑制糖酵解用于血糖。","reason":"具体考法：颜色题要同时说添加剂、标本类型、检验用途和是否混匀。","source":"教材第396—397页"},{"id":"ch15-core-7","title":"静脉采血顺序","answer":"血培养→枸橼酸钠→血清管→肝素管→EDTA管→糖酵解抑制管。","reason":"具体考法：先防微生物和添加剂污染，再保证凝血检测比例。","source":"教材第400—401页"},{"id":"ch15-core-8","title":"尿液防腐剂","answer":"不同检测项目选择不同防腐剂；定时尿先混匀、计总量，再按要求留送检部分。","reason":"具体考法：不能把甲苯、甲醛和浓盐酸互换使用。","source":"教材第405—407页"}],"numbers":[{"id":"ch15-number-1","title":"止血带时间","answer":"一般≤40 s","condition":"避免血液浓缩和检验偏差","source":"教材第400页"},{"id":"ch15-number-2","title":"血培养送检","answer":"采后≤2 h送达，室温保存","condition":"不得冷藏或冷冻","source":"教材第399—400页"},{"id":"ch15-number-3","title":"成人血培养","answer":"每瓶8～10 ml","condition":"需氧和厌氧成套采集","source":"教材第399页"},{"id":"ch15-number-4","title":"婴儿/幼儿血培养","answer":"婴儿1～3 ml；幼儿3～5 ml","condition":"按体重和瓶型调整","source":"教材第399页"},{"id":"ch15-number-5","title":"动脉血气送检","answer":"采后15 min内分析或冰浴送检","condition":"采后按压3～5 min，凝血异常延长","source":"教材第403页"},{"id":"ch15-number-6","title":"24小时尿标本","answer":"晨7时弃首次尿，至次晨7时收最后一次","condition":"混匀后取20～50 ml送检","source":"教材第406页"},{"id":"ch15-number-7","title":"尿培养","answer":"留取5～10 ml清洁中段尿","condition":"无菌容器并尽快送检","source":"教材第406—407页"},{"id":"ch15-number-8","title":"粪便常规","answer":"约5 g或挑取异常部分","condition":"清洁干燥容器","source":"教材第408页"},{"id":"ch15-number-9","title":"粪便培养","answer":"2～5 g或2～5 ml稀便","condition":"无菌带盖容器立即送检","source":"教材第408页"},{"id":"ch15-number-10","title":"隐血试验饮食","answer":"试验前3 d避免肉、肝、血制品和铁剂；连续3 d取材","condition":"从不同部位取材","source":"教材第409页"},{"id":"ch15-number-11","title":"痰培养","answer":"晨起深部痰，通常≥1 ml","condition":"无菌容器","source":"教材第411页"},{"id":"ch15-number-12","title":"痰细胞学固定","answer":"10%甲醛或95%乙醇","condition":"留取后立即固定","source":"教材第411页"},{"id":"ch15-number-13","title":"鼻咽拭子停留","answer":"15～30 s","condition":"充分吸附分泌物","source":"教材第413页"},{"id":"ch15-number-14","title":"定时尿保存","answer":"2～8℃；超过2 h不能检测时冷藏或加防腐剂","condition":"按检验项目选择防腐剂","source":"教材第407页"},{"id":"ch15-number-15","title":"蛲虫检查","answer":"午夜或清晨排便、洗澡前取材","condition":"透明胶带法","source":"教材第408页"},{"id":"ch15-number-16","title":"阿米巴滋养体","answer":"保温并立即送检","condition":"防止滋养体死亡","source":"教材第409页"},{"id":"ch15-number-17","title":"24小时痰标本","answer":"容器内加少量苯酚","condition":"从晨7时至次晨7时收集","source":"教材第411页"},{"id":"ch15-number-18","title":"诱导痰","answer":"雾化吸入3%氯化钠3～5 ml","condition":"观察支气管痉挛","source":"教材第411页"},{"id":"ch15-number-19","title":"培养痰量","answer":"细菌＞1 ml；真菌2～5 ml；分枝杆菌5～10 ml；寄生虫3～5 ml","condition":"按检验项目留取","source":"教材第411页"}],"compare":[{"title":"尿常规/尿培养","items":["A：清洁容器即可","B：无菌中段尿","决定性区别：检验目的决定无菌要求"]},{"title":"痰标本/唾液","items":["A：来自深部气道","B：口腔分泌物","决定性区别：深咳出痰才有代表性"]},{"title":"24小时尿开始/结束","items":["A：开始时排空不计","B：结束时尿液必须计入","决定性区别：首尾处理相反"]}],"questions":[{"id":"ch15-exam-1","title":"患者张某，男，52岁，有胃、渍殇史。近日来上腹部疼痛加剧，医嘱做大便隐血试验，此时应给患者食用那一组菜谱","topic":"粪便标本","options":["A. 卷心菜五香牛肉","B. 菠菜鸡蛋","C. 炒猪肝青菜","D. 鸡蛋土豆"],"answer":"正确答案：D．鸡蛋土豆","correct":["D"],"source":"教材第407—409页","paper":"武汉大学2014｜单项选择题"},{"id":"ch15-exam-2","title":"做尿培养和菌落计数时，正确的护理应是","topic":"尿标本","options":["A. 收集标本前用消毒液充分清洗外阴部","B. 留取在膀胱内停留有6~8h的尿液","C. 留取初始尿液置于清洁容器内","D. 应取患者停用抗菌药物后第3天的尿液","E. 若尿标本不能立即送检时应加适量防腐剂"],"answer":"正确答案：B．留取在膀胱内停留有6~8h的尿液","correct":["B"],"source":"教材第404—407页","paper":"暨南大学2013｜单项选择题"},{"id":"ch15-exam-3","title":"护士指导病人留取痰液标本时，不正确．．．的是：","topic":"标本原则","options":["A. 最好清晨留取痰液标本","B. 留取后及时送检","C. 用力咳出呼吸道深处痰液","D. 最后是在刷牙后留取痰标本","E. 要注意防止唾液及上呼吸道分泌物污染"],"answer":"正确答案：D．最后是在刷牙后留取痰标本","correct":["D"],"source":"教材第394—396页","paper":"四川大学2011｜单项选择题"},{"id":"ch15-exam-4","title":"患者贺某、女，需留24小时尿标本测量17－经类固醇，你在向病人介绍留取标本的方法时，应告诉患者加入下列哪种防腐剂，防止尿中激素被氧化","topic":"24小时尿标本","options":["A. 甲苯","B. 甲醛","C. 甲酸","D. 浓盐酸","E. 稀盐酸"],"answer":"正确答案：D．浓盐酸","correct":["D"],"source":"教材第406页","paper":"中南大学2011｜单项选择题"},{"id":"ch15-exam-5","title":"进行大便隐血试验的患者在试验期宜进食","topic":"粪便标本","options":["A. 萝卜","B. 肉类","C. 绿色蔬菜","D. 禽类","E. 铁剂2009年"],"answer":"正确答案：A．萝卜","correct":["A"],"source":"教材第407—409页","paper":"杭州师范大学2009｜单项选择题"},{"id":"ch15-exam-6","title":"下列有关血标本采集法的叙述，正确的是：","topic":"血液标本","options":["A. 同时抽取不同种类血标本时先注入血培养瓶","B. 血培养标本应在使用抗生素前采集","C. 亚急性细菌性心内膜炎血培养采血5～10ml","D. 全血标本沿抗凝管管壁缓慢注入后轻轻摇匀","E. 生化标本应在空腹时采集"],"answer":"正确答案：A．同时抽取不同种类血标本时先注入血培养瓶；B．血培养标本应在使用抗生素前采集；D．全血标本沿抗凝管管壁缓慢注入后轻轻摇匀；E．生化标本应在空腹时采集","correct":["A","B","D","E"],"source":"教材第396—403页","paper":"青岛大学2013｜多项选择题"},{"id":"ch15-exam-7","title":"采集血标本应注意：","topic":"血液标本","options":["A. 根据检验目的采集血量","B. 须空腹采血时应事先通知患者","C. 取全血标本应避免震荡","D. 血培养标本应注入干燥的无菌容器中","E. 血液中的泡沫勿注入试管内"],"answer":"正确答案：A．根据检验目的采集血量；B．须空腹采血时应事先通知患者；C．取全血标本应避免震荡；E．血液中的泡沫勿注入试管内","correct":["A","B","C","E"],"source":"教材第396—403页","paper":"陕西中医药大学2008-2009｜多项选择题"},{"id":"ch15-exam-8","title":"感染性心内膜炎采集血培养标本时，应注意","topic":"血液标本","options":["A. 采集标本需选在病人体温升高或寒战时","B. 采集前先试用某种抗生素，以利于医生选择抗生素的种类","C. 每次采血5毫升做需氧合厌氧培养，至少应培养3周","D. 急性病人应在入院后3小时内，每隔1小时采血一次，共取三次血标本","E. 应用抗生素的病人采集标本前无需停药"],"answer":"正确答案：A．采集标本需选在病人体温升高或寒战时；D．急性病人应在入院后3小时内，每隔1小时采血一次，共取三次血标本","correct":["A","D"],"source":"教材第396—403页","paper":"扬州大学2021｜多项选择题"},{"id":"ch15-exam-9","title":"某溃疡病患者主诉疼痛失去原有的节律性，近日在医院检查大便隐血试验阳性，首要考虑的是（）","topic":"粪便标本","options":["A. 幽门梗阻","B. 溃疡出血","C. 溃疡癌变","D. 溃疡穿孔","E. 溃疡病缓解"],"answer":"正确答案：C．溃疡癌变","correct":["C"],"source":"教材第407—409页","paper":"武汉科技大学2019｜单项选择题"},{"id":"ch15-exam-10","title":"张先生，45岁，因上消化道大出血被送至急诊室，值班护士在医生未到达前首先应","topic":"标本原则","options":["A. 记录病人到院时间和病情变化","B. 向家属了解病史，耐心解释","C. 通知住院处，办理入院手续","D. 测生命体征，建立静脉通路","E. 注射止血药物，抽血标本配血"],"answer":"正确答案：D．测生命体征，建立静脉通路","correct":["D"],"source":"教材第394—396页","paper":"山西医科大学2016｜单项选择题"}]},{"id":"ch16","number":16,"title":"疼痛患者的护理","page":"ch16-pain-care.html","lab":"ch16-learning-lab.html","core":[{"id":"ch16-core-1","title":"疼痛概念","answer":"疼痛是与实际或潜在组织损伤相关的主观体验，患者报告是重要依据。","reason":"具体考法：不能仅凭表情或生命体征否定疼痛。","source":"教材第415—419页"},{"id":"ch16-core-2","title":"疼痛评估","answer":"评估部位、性质、强度、时间、诱因、缓解因素、功能影响和既往处理。","reason":"具体考法：选择量表要匹配年龄、认知和沟通能力。","source":"教材第420—425页"},{"id":"ch16-core-3","title":"药物镇痛","answer":"按疼痛程度和机制选药，规律给药并预防恶心、便秘、呼吸抑制等不良反应。","reason":"具体考法：癌痛常考按时给药而非痛时才给。","source":"教材第425—431页"},{"id":"ch16-core-4","title":"非药物干预","answer":"放松、分散注意、音乐、冷/热、体位和心理支持可作为综合方案。","reason":"具体考法：不能以非药物方法替代必要镇痛。","source":"教材第431—439页"},{"id":"ch16-core-5","title":"效果评价","answer":"既看评分下降，也看睡眠、活动、咳嗽和康复目标是否改善。","reason":"具体考法：干预后必须在合适时间复评并记录。","source":"教材第429—441页"},{"id":"ch16-core-6","title":"疼痛评估原则","answer":"患者自我报告是清醒患者疼痛评估的首要依据，同时评估部位、性质、时间、诱因、功能影响和伴随症状。","reason":"具体考法：不能因生命体征正常或患者安静就否定疼痛。","source":"教材第421—427页"},{"id":"ch16-core-7","title":"量表选择","answer":"NRS适合能理解数字者；面部表情量表适合儿童或沟通受限者；行为量表用于不能自述者。","reason":"具体考法：量表必须匹配认知、语言和意识状态。","source":"教材第424—426页"},{"id":"ch16-core-8","title":"三阶梯镇痛","answer":"按疼痛程度阶梯用药，按时、个体化、口服优先并注意具体细节。","reason":"具体考法：爆发痛需解救药，持续痛不能只等疼痛严重再给药。","source":"教材第434—440页"}],"numbers":[{"id":"ch16-number-1","title":"NRS疼痛评分","answer":"0～10分","condition":"0无痛，分值越高疼痛越重","source":"教材第425页"},{"id":"ch16-number-2","title":"疼痛程度","answer":"1～3轻度；4～6中度；7～10重度","condition":"结合功能影响判断","source":"教材第425页"},{"id":"ch16-number-3","title":"疼痛控制目标","answer":"静息痛通常≤3分并稳定约3 d","condition":"结合个体治疗目标","source":"教材第440页"},{"id":"ch16-number-4","title":"24小时突破痛","answer":"＜3次","condition":"同时评估解救药使用","source":"教材第440页"},{"id":"ch16-number-5","title":"护理处置边界","answer":"评分≤5可先执行护理措施；＞5及时报告评估","condition":"严重疼痛需有效镇痛","source":"教材第426、440页"},{"id":"ch16-number-6","title":"癌痛三项量化目标","answer":"疼痛强度＜3；突破痛＜3次/24 h；解救药＜3次/24 h","condition":"用于评价控制效果","source":"教材第440页"},{"id":"ch16-number-7","title":"疼痛管理标准","answer":"常用‘321’或‘331’目标","condition":"结合教材具体指标理解，不孤立背数字","source":"教材第440页"},{"id":"ch16-number-8","title":"PCA观察周期","answer":"按1 h或4 h统计用药与按压","condition":"结合泵设置和镇静呼吸评估","source":"教材第438—440页"}],"compare":[{"title":"疼痛强度/疼痛行为","items":["A：患者主观评分","B：皱眉、保护动作等外显表现","决定性区别：行为少不代表不痛"]},{"title":"耐受/依赖","items":["A：同剂量效应下降","B：停药出现戒断或心理需求","决定性区别：概念不能混用"]},{"title":"按时给药/按需给药","items":["A：维持稳定镇痛","B：出现需要时使用","决定性区别：癌痛与急性间歇痛策略不同"]}],"questions":[{"id":"ch16-exam-1","title":"病人，男，56岁，胃癌末期住院，入院后采用吗啡口服给药镇痛。该药用药后主要不良反应包括（）","topic":"药物镇痛","options":["A. 便秘","B. 恶心、呕吐","C. 血小板减少","D. 直立性低血压","E. 低血压眩晕"],"answer":"正确答案：A．便秘；B．恶心、呕吐；D．直立性低血压；E．低血压眩晕","correct":["A","B","D","E"],"source":"教材第425—431页","paper":"暨南大学2021｜多项选择题"},{"id":"ch16-exam-2","title":"刘先生，56岁，肝癌晚期伴疼痛。护士需比较镇痛治疗前后的效果，最适宜的疼痛评估方法是","topic":"疼痛评估","options":["A. 面部表情疼痛评定法","B. 文字描述评定法","C. 数字评分法","D. 视觉模拟评分法","E. Prince-Henry评分法"],"answer":"正确答案：C．数字评分法","correct":["C"],"source":"教材第420—425页","paper":"浙江中医药大学2018｜单项选择题"},{"id":"ch16-exam-3","title":"下列措施符合世界卫生组织提出癌症三阶梯止痛治疗方案的原则的是（）","topic":"三阶梯镇痛","options":["A. 口服为主","B. 从小剂量开始","C. 痛时给药","D. 不应对药物限制过严","E. 非吗啡类药物效果不好时改用吗啡类药"],"answer":"正确答案：A．口服为主；B．从小剂量开始；D．不应对药物限制过严；E．非吗啡类药物效果不好时改用吗啡类药","correct":["A","B","D","E"],"source":"教材第434—440页","paper":"复旦大学2017｜多项选择题"},{"id":"ch16-exam-4","title":"患者刘某，肺癌切除术后伤口疼痛。下列有关护士对该患者健康教育内容的叙述，错误的是（）","topic":"疼痛概念","options":["A. 术后疼痛控制不佳，会引发术后并发症的产生","B. 镇痛药的不良反应及处理","C. 可适当夸大疼痛，以引起医生的重视并给予积极治疗","D. 术后镇痛的方式","E. 术后镇痛大致的费用"],"answer":"正确答案：C．可适当夸大疼痛，以引起医生的重视并给予积极治疗","correct":["C"],"source":"教材第415—419页","paper":"杭州师范大学2018｜单项选择题"},{"id":"ch16-exam-5","title":"下述有关“疼痛及其护理、治疗”的陈述恰当的为（）","topic":"疼痛评估","options":["A. 疼痛的基本特征为主观性及个体化","B. 患者的疼痛都可以通过应用药物控制","C. 疼痛评估指对疼痛强度的评估","D. PCA指患者家属控制镇痛","E. 不建议使用非药物镇痛措施"],"answer":"正确答案：A．疼痛的基本特征为主观性及个体化","correct":["A"],"source":"教材第420—425页","paper":"杭州师范大学2018｜单项选择题"},{"id":"ch16-exam-6","title":"下列措施不符合世界卫生组织提出癌症三阶梯止痛治疗方案原则的是（外护P161）","topic":"三阶梯镇痛","options":["A. 口服为主","B. 从小剂量开始","C. 必须限制用药剂量","D. 不应对药物限制过严","E. 非吗啡类药物效果不好时，改用吗啡类药"],"answer":"正确答案：C．必须限制用药剂量","correct":["C"],"source":"教材第434—440页","paper":"四川大学2009｜单项选择题"},{"id":"ch16-exam-7","title":"世界卫生组织在三阶梯镇痛治疗方案中提出，对于重度疼痛，优先考虑应用的药物为","topic":"三阶梯镇痛","options":["A. 弱阿片类药物","B. 强阿片类药物","C. 非甾体类抗炎镇痛药物","D. 激素类药物","E. 抗抑郁类药物"],"answer":"正确答案：B．强阿片类药物","correct":["B"],"source":"教材第434—440页","paper":"杭州师范大学2016｜单项选择题"},{"id":"ch16-exam-8","title":"丁某，胃癌晚期，平卧时疼痛，翻身时加剧，睡眠受干扰，要求用镇痛药，其疼痛级别为:","topic":"药物镇痛","options":["A. 0级","B. 1级","C. 2级","D. 3级","E. 4级"],"answer":"正确答案：C．2级","correct":["C"],"source":"教材第425—431页","paper":"湖南师范大学2012｜单项选择题"},{"id":"ch16-exam-9","title":"一胃癌住院病人告诉护士:其腹部很痛,难以忍受,睡眠受干扰,要求护士给他用镇痛药。根据WHO对疼痛程度的分级,该病人此时的疼痛是:","topic":"疼痛程度","options":["A. 0级","B. 1级","C. 2级","D. 3级","E. :‘1级"],"answer":"正确答案：C．2级","correct":["C"],"source":"教材第425页","paper":"中山大学2010｜单项选择题"},{"id":"ch16-exam-10","title":"对外科手术后疼痛，镇痛剂最好用在","topic":"药物镇痛","options":["A. 麻醉清醒前","B. 麻醉清醒后","C. 疼痛发作前","D. 疼痛发作时","E. 疼痛发作后"],"answer":"正确答案：C．疼痛发作前","correct":["C"],"source":"教材第425—431页","paper":"四川大学2011｜单项选择题"}]},{"id":"ch17","number":17,"title":"病情观察及危重患者的管理","page":"ch17-critical-care.html","lab":"ch17-learning-lab.html","core":[{"id":"ch17-core-1","title":"病情观察","answer":"从一般状态、意识、生命体征、瞳孔、出入量、治疗反应和心理变化综合判断。","reason":"具体考法：危险变化先报告并处理，不能等记录完再行动。","source":"教材第443—447页"},{"id":"ch17-core-2","title":"危重患者管理","answer":"保持气道、氧合、循环和体温，做好基础护理、管路管理与并发症预防。","reason":"具体考法：优先级题先抓生命威胁。","source":"教材第447—451页"},{"id":"ch17-core-3","title":"心肺复苏","answer":"识别无反应和无正常呼吸，呼救取AED并开始高质量胸外按压。","reason":"具体考法：按压频率、深度、回弹与中断时间常考。","source":"教材第452—458页"},{"id":"ch17-core-4","title":"洗胃","answer":"先评估适应证和禁忌，保护气道，选择合适溶液并观察出入液和生命体征。","reason":"具体考法：强腐蚀剂中毒和某些病情禁忌洗胃。","source":"教材第458—461页"},{"id":"ch17-core-5","title":"人工呼吸器","answer":"监测通气、氧合、同步性、报警、湿化和管路安全，预防相关并发症。","reason":"具体考法：报警先看患者，再查机器和管路。","source":"教材第461—464页"},{"id":"ch17-core-6","title":"GCS使用边界","answer":"睁眼、语言和运动三项相加；插管、失语、镇静等会影响评分解释。","reason":"具体考法：不能只报总分，要写出分项并结合干扰因素。","source":"教材第445—447页"},{"id":"ch17-core-7","title":"心肺复苏主线","answer":"确认环境安全、判断反应和呼吸、呼救取AED、开始高质量按压，尽早除颤。","reason":"具体考法：不要为反复测脉搏或长时间通气而延误按压。","source":"教材第452—458页"},{"id":"ch17-core-8","title":"洗胃禁忌与毒物","answer":"强腐蚀剂、惊厥未控制、上消化道出血或穿孔等禁忌洗胃；不同毒物的洗胃液和解毒剂不同。","reason":"具体考法：先判能不能洗，再选液体和气道保护。","source":"教材第459—462页"}],"numbers":[{"id":"ch17-number-1","title":"GCS总分","answer":"3～15分","condition":"分数越低意识障碍越重","source":"教材第446页"},{"id":"ch17-number-2","title":"GCS分度","answer":"13～14轻度；9～12中度；3～8重度","condition":"＜8分常提示昏迷并关注气道","source":"教材第446页"},{"id":"ch17-number-3","title":"脉搏判断","answer":"5～10 s","condition":"成人心搏骤停评估","source":"教材第454页"},{"id":"ch17-number-4","title":"胸外按压频率","answer":"100～120次/min","condition":"减少中断","source":"教材第455页"},{"id":"ch17-number-5","title":"成人按压深度","answer":"5～6 cm","condition":"充分回弹","source":"教材第455页"},{"id":"ch17-number-6","title":"儿童/婴儿按压深度","answer":"儿童约5 cm、婴儿约4 cm，均约胸廓前后径1/3","condition":"避免过深或过浅","source":"教材第458页"},{"id":"ch17-number-7","title":"按压通气比","answer":"30:2","condition":"单人成人基础生命支持","source":"教材第455页"},{"id":"ch17-number-8","title":"有脉搏人工呼吸","answer":"每6 s 1次，约10次/min；每2 min复查脉搏","condition":"成人呼吸停止但有脉搏","source":"教材第458页"},{"id":"ch17-number-9","title":"有效按压血压","answer":"收缩压可达≥60 mmHg","condition":"结合颈动脉搏动等判断","source":"教材第455页"},{"id":"ch17-number-10","title":"洗胃时机","answer":"中毒后4～6 h内效果较好","condition":"仍需结合毒物性质和禁忌","source":"教材第459页"},{"id":"ch17-number-11","title":"洗胃液","answer":"25～38℃，总量约10～20 L，每次300～500 ml","condition":"出入量基本相等","source":"教材第459—460页"},{"id":"ch17-number-12","title":"简易呼吸器","answer":"成人每次约500 ml，约10次/min","condition":"以胸廓起伏为准","source":"教材第461页"},{"id":"ch17-number-13","title":"危重尿量","answer":"＜30 ml/h需警惕灌注不足","condition":"连续监测趋势","source":"教材第446页"},{"id":"ch17-number-14","title":"洗胃后活性炭","answer":"常按1 g/kg","condition":"按毒物和医嘱使用","source":"教材第460页"},{"id":"ch17-number-15","title":"高级气道通气","answer":"持续按压时约每6 s通气1次","condition":"避免过度通气","source":"教材第458页"}],"compare":[{"title":"先查机器/先看患者","items":["A：报警时先确认患者安全","B：随后查管路与设备","决定性区别：患者永远优先"]},{"title":"呼吸停止/濒死喘息","items":["A：均不能视为正常呼吸","B：濒死喘息仍需启动复苏","决定性区别：不要因偶发喘息延误"]},{"title":"催吐/洗胃","items":["A：依靠呕吐排出","B：胃管反复灌洗","决定性区别：适应证禁忌不同"]}],"questions":[{"id":"ch17-exam-1","title":"女性，60岁。确诊为慢性阻塞性肺疾病15年，加重2周入院。入院时神志清楚，动脉血气分析示PaO₂40mmHg，PaCO₂55mmHg.吸入40％浓度氧后，患者呼之不应，查动脉血气分析示PaCO₂90mmHg，PaO₂75mmHg.患者出现意识障碍的原因是","topic":"有效按压血压","options":["A. 感染加重","B. 气道阻力增加","C. 呼吸中枢受到抑制","D. 脑血管意外","E. 感染中毒性脑病"],"answer":"正确答案：C．呼吸中枢受到抑制","correct":["C"],"source":"教材第455页","paper":"杭州师范大学2019｜单项选择题"},{"id":"ch17-exam-2","title":"当急性中毒患者诊断不明时，给予处理时应选择的洗胃液是（）","topic":"洗胃","options":["A. 牛奶","B. 1:15000高锰酸钾","C. 2%～4%碳酸氢钠","D. 3%过氧化氢","E. 温开水或生理盐水"],"answer":"正确答案：E．温开水或生理盐水","correct":["E"],"source":"教材第458—461页","paper":"暨南大学2019｜单项选择题"},{"id":"ch17-exam-3","title":"男性，28岁，自觉突然心慌、胸闷，听诊心率160次/分心律齐，心音均等，血压正常。若心电图出现完全不规则的大波浪状曲线，且QRS波与T波消失。你考虑下列哪项处理不妥","topic":"心肺复苏","options":["A. 准备抢救用品","B. 可于心内注射利多卡因","C. 可施行同步电除颤复律","D. 立即做胸外按压和口对口人工呼吸","E. 立即通知医生进行抢救"],"answer":"正确答案：C．可施行同步电除颤复律","correct":["C"],"source":"教材第452—458页","paper":"青岛大学2011｜单项选择题"},{"id":"ch17-exam-4","title":"男性，53岁，十二指肠溃疡10年。近1个月以来，上腹部胀满不适，反复呕吐带酸味宿食，呕吐后患者自觉胃部舒适。诊断瘢痕性幽门梗阻，拟手术治疗。术前护理措施中，不正确的是:","topic":"洗胃","options":["A. 纠正电解质和酸碱失衡","B. 记录出入水量","C. 提供营养支持","D. 留置胃管","E. 每晚用冰盐水洗胃"],"answer":"正确答案：E．每晚用冰盐水洗胃","correct":["E"],"source":"教材第458—461页","paper":"汕头大学2022｜单项选择题"},{"id":"ch17-exam-5","title":"患者，男性，48岁，既往有乙型肝炎病史，此次因食管静脉曲张、上消化道出血入院。检查发现其肝功能轻度损害。对该患者的护理措施中，错误的是","topic":"洗胃","options":["A. 吸氧","B. 应用三腔管压迫止血","C. 应用硫酸镁溶液导泻","D. 补钾、控制钠的摄人量","E. 温生理盐水洗胃"],"answer":"正确答案：E．温生理盐水洗胃","correct":["E"],"source":"教材第458—461页","paper":"四川大学2013｜单项选择题"},{"id":"ch17-exam-6","title":"患者，男性，73岁。表现为几次严重的呕血和黑粪。体格检查提示体位性低血压。针对该病人中首先采取的处理措施是","topic":"洗胃","options":["A. 放置鼻胃管和洗胃","B. 立即建立静脉通路，进行补液和输血","C. 静脉使用H2受体拮抗剂止血","D. 急诊上消化道内镜","E. 急诊外科咨询"],"answer":"正确答案：B．立即建立静脉通路，进行补液和输血","correct":["B"],"source":"教材第458—461页","paper":"青岛大学2009｜单项选择题"},{"id":"ch17-exam-7","title":"患者男性，26岁，因车祸后意识障碍Sh入院。患者家属代诉患者意识障碍后曾在送来医院的途中曾清醒15m血，后再次陷入昏迷状态，呼之不应。根据病人家属的主诉，可初步诊断病人为","topic":"GCS总分","options":["A. 脑震荡c脑内血肿","B. 脑挫裂伤","D. 硬膜下血肿","E. 硬膜外血肿"],"answer":"正确答案：E．硬膜外血肿","correct":["E"],"source":"教材第446页","paper":"湖州师范学院2018｜单项选择题"},{"id":"ch17-exam-8","title":"男性，38岁，突然呕血1500ml，伴柏油样大便，急诊入院，查体：血压80／50mmHg，心率120次／min,此时最主要的护理诊断是","topic":"简易呼吸器","options":["A. 体液不足","B. 活动无耐力","C. 有受伤的危险","D. 意识障碍","E. 潜在并发症"],"answer":"正确答案：A．体液不足","correct":["A"],"source":"教材第461页","paper":"杭州师范大学2016｜单项选择题"},{"id":"ch17-exam-9","title":"性患者，73岁，出现呕血、黑便4天。护理查体提示体位性低血压。应首先采取的处理措施是","topic":"洗胃","options":["A. 放置鼻胃管和洗胃","B. 静脉使用H2受体拮抗剂","C. 立即建立静脉通路，进行补液和输血","D. 急诊上消化道内镜","E. 急诊外科咨询"],"answer":"正确答案：C．立即建立静脉通路，进行补液和输血","correct":["C"],"source":"教材第458—461页","paper":"江南大学2017｜单项选择题"},{"id":"ch17-exam-10","title":"病人王某，女，50岁，因吵架而服乐果，2小时后送入医院，急诊室护士应立即给予","topic":"洗胃","options":["A. 口服牛奶","B. 3%碳酸氢铀洗胃","C. 1:20000高锚酸饵溶液洗胃","D. 50%硫酸馍导泻","E. 快速补液"],"answer":"正确答案：B．3%碳酸氢铀洗胃","correct":["B"],"source":"教材第458—461页","paper":"湖州师范学院2018｜单项选择题"}]},{"id":"ch18","number":18,"title":"临终护理","page":"ch18-end-of-life.html","lab":"ch18-learning-lab.html","core":[{"id":"ch18-core-1","title":"临终关怀","answer":"目标是减轻痛苦、维护尊严和提高剩余生命质量，同时支持家属。","reason":"具体考法：不是放弃治疗，而是目标转向舒适与价值。","source":"教材第466—471页"},{"id":"ch18-core-2","title":"死亡与濒死","answer":"依据不可逆生命功能停止和规范判断理解死亡过程。","reason":"具体考法：不能用单一表现随意宣布死亡。","source":"教材第471—474页"},{"id":"ch18-core-3","title":"生理护理","answer":"持续评估疼痛、呼吸困难、分泌物、口腔皮肤、营养排泄和睡眠。","reason":"具体考法：措施以舒适、安全和患者愿望为中心。","source":"教材第474—476页"},{"id":"ch18-core-4","title":"心理社会护理","answer":"倾听、允许表达、提供真实适量信息，尊重文化宗教与家庭角色。","reason":"具体考法：不同反应可反复出现，不能机械套五阶段。","source":"教材第476—479页"},{"id":"ch18-core-5","title":"死亡后护理","answer":"尊重遗体与家属，按规定确认、清洁、标识、处理物品和记录。","reason":"具体考法：有导管或特殊检查要求时按规定保留或处理。","source":"教材第479—482页"},{"id":"ch18-core-6","title":"脑死亡判断","answer":"需按规范综合判定不可逆昏迷、脑干反射消失和自主呼吸停止，并排除低温、药物等可逆因素。","reason":"具体考法：深昏迷或使用呼吸机不能单独等于脑死亡。","source":"教材第471—474页"}],"numbers":[{"id":"ch18-number-1","title":"临床死亡可逆时间","answer":"一般约5～6 min","condition":"尽快复苏可减少不可逆脑损伤","source":"教材第473页"},{"id":"ch18-number-2","title":"脑死亡观察","answer":"规范观察1 h后脱离呼吸机约3 min无自主呼吸，并需重复确认","condition":"必须排除低温和药物影响","source":"教材第472页"},{"id":"ch18-number-3","title":"尸冷速度","answer":"前10 h约下降1℃/h；其后约0.5℃/h","condition":"约24 h接近环境温度","source":"教材第473页"},{"id":"ch18-number-4","title":"尸斑","answer":"死亡后2～4 h开始出现","condition":"低垂部位明显","source":"教材第473页"},{"id":"ch18-number-5","title":"尸僵","answer":"1～3 h开始，4～6 h遍及全身，12～16 h达高峰，24 h后逐渐缓解","condition":"用于死亡后变化识别","source":"教材第473页"},{"id":"ch18-number-6","title":"尸体腐败","answer":"约24 h先见于右下腹","condition":"受环境温度等影响","source":"教材第473页"},{"id":"ch18-number-7","title":"临终热水袋","answer":"水温＜50℃","condition":"防止低温与烫伤","source":"教材第475页"},{"id":"ch18-number-8","title":"脑死亡排除低温","answer":"体温＜32.2℃不能贸然判定","condition":"同时排除巴比妥类等中枢抑制药","source":"教材第472页"},{"id":"ch18-number-9","title":"临终心理五阶段","answer":"否认、愤怒、协议、忧郁、接受","condition":"不一定按固定顺序出现","source":"教材第469—470页"}],"compare":[{"title":"临终关怀/停止照护","items":["A：积极控制症状和支持","B：不再提供护理","决定性区别：目标改变但护理更精细"]},{"title":"尸冷/尸斑","items":["A：体温下降","B：血液坠积形成斑块","决定性区别：机制和表现不同"]},{"title":"同理/空泛安慰","items":["A：承认感受并倾听","B：要求患者别难过","决定性区别：回应真实需要而非压制情绪"]}],"questions":[{"id":"ch18-exam-1","title":"患者男，69岁，肝癌晚期，入院时昏迷，呼之不应，心率40次/分，血压40/20mmHg，呼吸微弱，此期属于","topic":"生理护理","options":["A. 深昏迷期","B. 濒死期","C. 临床死亡期","D. 生物学死亡期","E. 脑死亡期"],"answer":"正确答案：B．濒死期","correct":["B"],"source":"教材第474—476页","paper":"四川大学2009｜单项选择题"},{"id":"ch18-exam-2","title":"下列关于死亡过程的描述、正确的是:","topic":"临床死亡可逆时间","options":["A. 濒死期生命已处于不可逆阶段","B. 临床死亡期病人的神经系统及其他各器官系统的新陈代谢停止，组织与细胞相继死亡","C. 在低温条件下，尤其是头部降温脑耗氧降低时，临床死亡期可延长达1小时","D. 生物学死亡期重要器官的代谢过程尚未停止","E. 自生物学死亡期是临床上判断死亡的标准"],"answer":"正确答案：C．在低温条件下，尤其是头部降温脑耗氧降低时，临床死亡期可延长达1小时","correct":["C"],"source":"教材第473页","paper":"河南科技大学2019｜单项选择题"},{"id":"ch18-exam-3","title":"以下关于临终关怀理念的叙述错误的是","topic":"临终关怀","options":["A. 丰富患者生命，提高其生存质量","B. 采取积极措施帮助病人痊愈","C. 尊重临终患者的尊严和权利","D. 在照顾患者同时也为家属提供心理和社会支持","E. 是社会进步的一种表现形式"],"answer":"正确答案：B．采取积极措施帮助病人痊愈","correct":["B"],"source":"教材第466—471页","paper":"杭州师范大学2012｜单项选择题"},{"id":"ch18-exam-4","title":"下列有关临终关怀的描述，不正确的是","topic":"临终关怀","options":["A. 提供临终患者全面照顾","B. 用人为方法帮助患者无痛苦死亡","C. 维护临终患者家属的身心健康","D. 帮助临终患者安宁走完人生最后历程","E. 提高临终患者生命质量"],"answer":"正确答案：B．用人为方法帮助患者无痛苦死亡","correct":["B"],"source":"教材第466—471页","paper":"复旦大学2016｜单项选择题"},{"id":"ch18-exam-5","title":"护士进行尸体护理应在","topic":"生理护理","options":["A. 患者心跳、呼吸停止后","B. 患者脑电波平直后","C. 患者意识丧失后","D. 医生开具死亡诊断书后","E. 对患者抢救效果不显著"],"answer":"正确答案：D．医生开具死亡诊断书后","correct":["D"],"source":"教材第474—476页","paper":"复旦大学2015｜单项选择题"},{"id":"ch18-exam-6","title":"濒死期病人的临床表现是（）","topic":"死亡与濒死","options":["A. 呼吸停止","B. 心跳停止","C. 反射性反应消失","D. 体温逐渐下降，接近室温","E. 呼吸衰竭"],"answer":"正确答案：E．呼吸衰竭","correct":["E"],"source":"教材第471—474页","paper":"武汉科技大学2019｜单项选择题"},{"id":"ch18-exam-7","title":"临终关怀的目的是帮助病人（）","topic":"临终关怀","options":["A. 认识死亡是一种自然过程","B. 处于舒适，安宁状态","C. 提高生命质量","D. 延长生命","E. 平静地接受死亡"],"answer":"正确答案：A．认识死亡是一种自然过程；B．处于舒适，安宁状态；C．提高生命质量；E．平静地接受死亡","correct":["A","B","C","E"],"source":"教材第466—471页","paper":"河南大学2008｜多项选择题"},{"id":"ch18-exam-8","title":"被誉为“点燃了临终关怀运动灯塔”的临终关怀机构是（）","topic":"临终关怀","options":["A. 美国新港临终关怀病院","B. 西欧修道院","C. 美国圣克里斯多弗临终关怀院","D. 加拿大姑息护理协会","E. 天津医学院临终关怀研究中心"],"answer":"正确答案：C．美国圣克里斯多弗临终关怀院","correct":["C"],"source":"教材第466—471页","paper":"武汉科技大学2019｜单项选择题"},{"id":"ch18-exam-9","title":"尸体护理时，要将尸体仰卧放平，头下垫一软枕，其目的为","topic":"生理护理","options":["A. 保持良好姿势","B. 以防面部淤血变色","C. 使尸体易于保存","D. 防止下颌骨脱位","E. 方便进行尸体护理"],"answer":"正确答案：B．以防面部淤血变色","correct":["B"],"source":"教材第474—476页","paper":"陕西中医药大学2008-2009｜单项选择题"},{"id":"ch18-exam-10","title":"中国第一所临终关怀医院—南汇护理院诞生于","topic":"临终关怀","options":["A. 1991年3月","B. 1993年5月","C. 1976年12月","D. 1988年5月","E. 1988年10月"],"answer":"正确答案：D．1988年5月","correct":["D"],"source":"教材第466—471页","paper":"四川大学2012｜单项选择题"}]}]};